-- ============================================================
-- migrations/20261006120000_core_tables.sql
-- ============================================================
-- Cute Kids Academy parent portal: core tables (Prompt 3, Part 1).
-- Row-level security is switched on in a later migration; every table here is
-- locked down there. Nothing in this file contains real family data.

-- ---------------------------------------------------------------------------
-- People
-- ---------------------------------------------------------------------------
create table public.profiles (
  id          uuid primary key references auth.users (id),
  full_name   text not null,
  phone       text,
  language    text not null default 'ar' check (language in ('ar', 'en')),
  role        text not null check (role in ('parent', 'teacher', 'admin', 'manager', 'owner')),
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
comment on table public.profiles is 'One row per login. Deactivated users keep their row so history stays intact.';

create table public.classes (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  age_group        text not null,
  head_teacher_id  uuid references public.profiles (id),
  created_at       timestamptz not null default now()
);

create table public.children (
  id             uuid primary key default gen_random_uuid(),
  full_name      text not null,
  date_of_birth  date not null,
  class_id       uuid references public.classes (id),
  active         boolean not null default true,
  created_at     timestamptz not null default now()
);
create index children_class_idx on public.children (class_id);

-- A child can have two parents; each parent has their own login.
create table public.parent_children (
  parent_id  uuid not null references public.profiles (id),
  child_id   uuid not null references public.children (id),
  created_at timestamptz not null default now(),
  primary key (parent_id, child_id)
);
create index parent_children_child_idx on public.parent_children (child_id);

create table public.staff_classes (
  staff_id  uuid not null references public.profiles (id),
  class_id  uuid not null references public.classes (id),
  primary key (staff_id, class_id)
);

-- ---------------------------------------------------------------------------
-- Submissions (complaints and safety concerns) and their timeline
-- Ratings are NOT stored here: they live in public.ratings so that admin and
-- teachers, who can read submissions, can never read them.
-- ---------------------------------------------------------------------------
create table public.submissions (
  id                   uuid primary key default gen_random_uuid(),
  ref_no               bigint generated always as identity unique,
  parent_id            uuid not null references public.profiles (id),
  child_id             uuid not null references public.children (id),
  type                 text not null check (type in ('complaint', 'safety_concern')),
  title                text not null check (length(btrim(title)) > 0),
  description          text not null check (length(btrim(description)) > 0),
  urgency              text not null default 'can_wait' check (urgency in ('critical', 'urgent', 'can_wait')),
  status               text not null default 'received'
                         check (status in ('received', 'acknowledged', 'in_progress', 'resolved', 'closed')),
  escalation_level     smallint not null default 1 check (escalation_level between 1 and 4),
  assigned_to          uuid references public.profiles (id),
  about_staff_member   uuid references public.profiles (id),
  acknowledge_by       timestamptz,
  resolve_by           timestamptz,
  acknowledged_at      timestamptz,
  resolved_at          timestamptz,
  parent_satisfied     boolean,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now(),
  constraint not_assigned_to_subject check (assigned_to is null or about_staff_member is null or assigned_to <> about_staff_member)
);
create index submissions_parent_idx   on public.submissions (parent_id);
create index submissions_child_idx    on public.submissions (child_id);
create index submissions_deadline_idx on public.submissions (resolve_by) where status not in ('resolved', 'closed');
create index submissions_assigned_idx on public.submissions (assigned_to);

create table public.submission_events (
  id                 uuid primary key default gen_random_uuid(),
  submission_id      uuid not null references public.submissions (id),
  actor_id           uuid references public.profiles (id),   -- null = the system
  actor_name         text,                                    -- copied at write time so history survives deactivation
  event_type         text not null check (event_type in (
                       'created', 'acknowledged', 'status_changed', 'urgency_changed', 'assigned',
                       'escalated', 'update', 'internal_note', 'parent_reply', 'resolved',
                       'reopened', 'satisfaction', 'investigation_step')),
  message            text,
  old_value          text,
  new_value          text,
  visible_to_parent  boolean not null default false,
  created_at         timestamptz not null default now()
);
create index submission_events_sub_idx on public.submission_events (submission_id, created_at);
comment on column public.submission_events.visible_to_parent is
  'false = internal staff note or internal system event. Never shown to parents.';

-- ---------------------------------------------------------------------------
-- Accidents (logged by staff) and investigations
-- ---------------------------------------------------------------------------
create table public.incidents (
  id               uuid primary key default gen_random_uuid(),
  child_id         uuid not null references public.children (id),
  occurred_at      timestamptz not null,
  location         text not null,
  what_happened    text not null,
  injury           text,
  first_aid        text,
  severity         text not null default 'minor' check (severity in ('minor', 'needs_attention', 'serious')),
  witnesses        text[] not null default '{}',   -- staff names only, never other children
  parent_called_at timestamptz,
  parent_signed_at timestamptz,                    -- set when the parent taps "I've read this report"
  submission_id    uuid references public.submissions (id),
  reported_by      uuid not null references public.profiles (id),
  created_at       timestamptz not null default now(),
  -- Anything beyond a minor scrape must record that the parent was called.
  constraint parent_called_if_not_minor check (severity = 'minor' or parent_called_at is not null)
);
create index incidents_child_idx on public.incidents (child_id, occurred_at desc);

-- The part of an investigation parents may see.
create table public.investigations (
  id                  uuid primary key default gen_random_uuid(),
  incident_id         uuid unique references public.incidents (id),
  submission_id       uuid unique references public.submissions (id),
  assigned_to         uuid references public.profiles (id),
  status              text not null default 'open' check (status in ('open', 'closed')),
  findings_for_parent text,                         -- written without other children's names
  parent_response     text check (parent_response in ('acknowledged', 'disagreed')),
  parent_responded_at timestamptz,
  opened_at           timestamptz not null default now(),
  closed_at           timestamptz,
  created_at          timestamptz not null default now(),
  constraint linked_to_something check (incident_id is not null or submission_id is not null)
);

-- The part only manager and owner may see (admin and parents never).
create table public.investigation_internal (
  investigation_id  uuid primary key references public.investigations (id),
  internal_findings text,
  staff_statements  text,
  actions_taken     text,
  updated_at        timestamptz not null default now()
);

create table public.investigation_steps (
  id               uuid primary key default gen_random_uuid(),
  investigation_id uuid not null references public.investigations (id),
  step             text not null check (step in (
                     'opened', 'parent_called', 'facts_gathered', 'findings',
                     'actions_taken', 'parent_informed', 'closed')),
  completed_by     uuid references public.profiles (id),
  completed_at     timestamptz not null default now(),
  unique (investigation_id, step)
);

-- ---------------------------------------------------------------------------
-- Ratings (manager and owner only) and attachments
-- ---------------------------------------------------------------------------
create table public.ratings (
  id                   uuid primary key default gen_random_uuid(),
  parent_id            uuid not null references public.profiles (id),
  child_id             uuid not null references public.children (id),
  class_id             uuid references public.classes (id),
  month                date not null default (date_trunc('month', now() at time zone 'Africa/Cairo'))::date
                         check (month = date_trunc('month', month)::date),
  care_score           smallint not null check (care_score between 1 and 5),
  communication_score  smallint not null check (communication_score between 1 and 5),
  daily_reports_score  smallint not null check (daily_reports_score between 1 and 5),
  comment              text,
  compliment_staff_id  uuid references public.profiles (id),
  compliment_text      text,
  created_at           timestamptz not null default now(),
  unique (parent_id, child_id, month)
);

create table public.attachments (
  id             uuid primary key default gen_random_uuid(),
  submission_id  uuid not null references public.submissions (id),
  uploaded_by    uuid not null references public.profiles (id),
  storage_path   text not null unique,              -- "<submission_id>/<file>" in the private bucket
  file_name      text not null,
  mime_type      text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp', 'image/heic')),
  size_bytes     integer not null check (size_bytes > 0 and size_bytes <= 5242880),  -- 5 MB
  created_at     timestamptz not null default now()
);
create index attachments_sub_idx on public.attachments (submission_id);

-- ============================================================
-- migrations/20261006120100_working_hours.sql
-- ============================================================
-- Working-hours clock (Prompt 3): Sunday-Thursday, 08:00-18:00, Africa/Cairo.
-- Friday and Saturday are not business days. All maths is done on Cairo wall-clock
-- time, so daylight saving is handled by the time-zone database.

create function public.cka_is_work_day(d date) returns boolean
language sql immutable as $$
  select extract(dow from d) in (0, 1, 2, 3, 4)   -- 0 = Sunday ... 4 = Thursday
$$;

create function public.cka_next_work_day(d date) returns date
language plpgsql immutable as $$
declare n date := d + 1;
begin
  while not public.cka_is_work_day(n) loop n := n + 1; end loop;
  return n;
end $$;

-- First moment at or after t (Cairo wall-clock) that is inside working hours.
create function public.cka_working_start(t timestamp) returns timestamp
language plpgsql immutable as $$
begin
  if not public.cka_is_work_day(t::date) then
    return public.cka_next_work_day(t::date) + time '08:00';
  elsif t::time < time '08:00' then
    return t::date + time '08:00';
  elsif t::time >= time '18:00' then
    return public.cka_next_work_day(t::date) + time '08:00';
  end if;
  return t;
end $$;

-- Add working hours, only counting time inside Sun-Thu 08:00-18:00.
create function public.cka_add_working_hours(t timestamp, hrs numeric) returns timestamp
language plpgsql immutable as $$
declare
  cur timestamp := public.cka_working_start(t);
  remaining interval := make_interval(secs => hrs * 3600);
  avail interval;
begin
  loop
    avail := (cur::date + time '18:00') - cur;
    if remaining <= avail then return cur + remaining; end if;
    remaining := remaining - avail;
    cur := public.cka_next_work_day(cur::date) + time '08:00';
  end loop;
end $$;

-- Add business days, keeping the time of day (a request in at 14:00 on Sunday
-- with 1 business day is due Monday 14:00; Thursday 14:00 is due Sunday 14:00).
create function public.cka_add_business_days(t timestamp, n int) returns timestamp
language plpgsql immutable as $$
declare
  cur timestamp := public.cka_working_start(t);
  i int;
begin
  for i in 1..n loop
    cur := public.cka_next_work_day(cur::date) + cur::time;
  end loop;
  return cur;
end $$;

-- Deadlines for a submission, as real timestamps.
--   critical : acknowledge in 1 hour (any hour of the day); investigation opened by closing time
--              of the first working day on or after submission.
--   urgent   : acknowledge in 2 working hours; resolve in 1 business day (our reading of "24 hours").
--   can_wait : acknowledge in 1 business day; resolve in 3 business days.
create function public.cka_deadlines(p_urgency text, p_from timestamptz,
                                     out acknowledge_by timestamptz, out resolve_by timestamptz)
language plpgsql immutable as $$
declare local_t timestamp := p_from at time zone 'Africa/Cairo';
begin
  if p_urgency = 'critical' then
    acknowledge_by := p_from + interval '1 hour';
    resolve_by := (public.cka_working_start(local_t)::date + time '18:00') at time zone 'Africa/Cairo';
  elsif p_urgency = 'urgent' then
    acknowledge_by := public.cka_add_working_hours(local_t, 2) at time zone 'Africa/Cairo';
    resolve_by := public.cka_add_business_days(local_t, 1) at time zone 'Africa/Cairo';
  elsif p_urgency = 'can_wait' then
    acknowledge_by := public.cka_add_business_days(local_t, 1) at time zone 'Africa/Cairo';
    resolve_by := public.cka_add_business_days(local_t, 3) at time zone 'Africa/Cairo';
  else
    raise exception 'unknown urgency %', p_urgency;
  end if;
end $$;

-- ============================================================
-- migrations/20261006120200_access_helpers.sql
-- ============================================================
-- Who-can-see-what helpers (Prompt 3). Used by the row-level security policies.
-- They are SECURITY DEFINER so they can look at tables without triggering the
-- policies on those tables (which would loop). Each one only answers a yes/no
-- or role question about the CURRENT user (auth.uid()).

-- Role of the current user. NULL when not logged in or when the account is deactivated,
-- so a deactivated user instantly loses all access.
create function public.auth_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid() and active
$$;

create function public.is_management() returns boolean   -- admin, manager or owner
language sql stable security definer set search_path = public as $$
  select coalesce(public.auth_role() in ('admin', 'manager', 'owner'), false)
$$;

create function public.is_manager_or_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.auth_role() in ('manager', 'owner'), false)
$$;

-- Does the current teacher work in this class (or head it)?
create function public.teaches_class(p_class uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'teacher' and p_class is not null and (
    exists (select 1 from public.staff_classes sc where sc.staff_id = auth.uid() and sc.class_id = p_class)
    or exists (select 1 from public.classes c where c.id = p_class and c.head_teacher_id = auth.uid())
  )
$$;

-- Can the current user see this child at all?
create function public.can_see_child(p_child uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case public.auth_role()
    when 'admin' then true
    when 'manager' then true
    when 'owner' then true
    when 'teacher' then exists (
      select 1 from public.children c where c.id = p_child and public.teaches_class(c.class_id))
    when 'parent' then exists (
      select 1 from public.parent_children pc where pc.parent_id = auth.uid() and pc.child_id = p_child)
    else false
  end
$$;

create function public.owns_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'parent' and exists (
    select 1 from public.submissions s where s.id = p_submission and s.parent_id = auth.uid())
$$;

-- Can the current STAFF member see this submission? (Parents use owns_submission.)
-- Teachers: children in their classes, never a complaint about themselves.
create function public.staff_can_see_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when public.is_management() then exists (select 1 from public.submissions s where s.id = p_submission)
    when public.auth_role() = 'teacher' then exists (
      select 1 from public.submissions s
      where s.id = p_submission
        and public.can_see_child(s.child_id)
        and s.about_staff_member is distinct from auth.uid())
    else false
  end
$$;

-- Does this investigation belong to the current parent (via their submission or their child's incident)?
create function public.parent_owns_investigation(p_investigation uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'parent' and exists (
    select 1 from public.investigations i
    left join public.submissions s on s.id = i.submission_id
    left join public.incidents n on n.id = i.incident_id
    where i.id = p_investigation
      and (s.parent_id = auth.uid()
           or (n.child_id is not null and public.can_see_child(n.child_id))))
$$;

-- Teachers may see the parents of children in their classes (for contact), nobody else's.
create function public.teacher_sees_parent(p_parent uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.auth_role() = 'teacher' and exists (
    select 1 from public.parent_children pc where pc.parent_id = p_parent and public.can_see_child(pc.child_id))
$$;

-- Name of whoever is handling a parent's own submission (parents cannot read other profiles).
create function public.submission_handler_name(p_submission uuid) returns text
language sql stable security definer set search_path = public as $$
  select p.full_name
  from public.submissions s join public.profiles p on p.id = s.assigned_to
  where s.id = p_submission and public.owns_submission(p_submission)
$$;

revoke all on function
  public.auth_role(), public.is_management(), public.is_manager_or_owner(), public.teaches_class(uuid),
  public.can_see_child(uuid), public.owns_submission(uuid), public.staff_can_see_submission(uuid),
  public.parent_owns_investigation(uuid), public.teacher_sees_parent(uuid), public.submission_handler_name(uuid)
from public;
grant execute on function
  public.auth_role(), public.is_management(), public.is_manager_or_owner(), public.teaches_class(uuid),
  public.can_see_child(uuid), public.owns_submission(uuid), public.staff_can_see_submission(uuid),
  public.parent_owns_investigation(uuid), public.teacher_sees_parent(uuid), public.submission_handler_name(uuid)
to authenticated;

-- ============================================================
-- migrations/20261006120300_rules_and_triggers.sql
-- ============================================================
-- Automatic rules (Prompt 3). These run inside the database, so they apply no matter
-- which screen or script writes the data.

create function public.cka_touch_updated_at() returns trigger
language plpgsql as $$
begin new.updated_at := now(); return new; end $$;

create trigger profiles_touch before update on public.profiles
  for each row execute function public.cka_touch_updated_at();

-- A child can have at most two parent accounts.
create function public.cka_limit_two_parents() returns trigger
language plpgsql as $$
begin
  if (select count(*) from public.parent_children where child_id = new.child_id) >= 2 then
    raise exception 'A child can have at most two parents';
  end if;
  return new;
end $$;
create trigger parent_children_max_two before insert on public.parent_children
  for each row execute function public.cka_limit_two_parents();

-- ---------------------------------------------------------------------------
-- Submissions: normalise on insert, guard on update, log every change
-- ---------------------------------------------------------------------------
create function public.cka_submission_before_insert() returns trigger
language plpgsql as $$
declare d record;
begin
  -- The client never decides these; the database does.
  new.created_at := now();
  new.updated_at := now();
  new.status := 'received';
  new.acknowledged_at := null;
  new.resolved_at := null;
  new.parent_satisfied := null;

  if public.auth_role() = 'parent' then
    new.parent_id := auth.uid();
    new.assigned_to := null;
    if new.urgency = 'critical' and new.type = 'complaint' then
      raise exception 'Parents choose Urgent or Can wait; Critical is set automatically for safety concerns';
    end if;
  end if;

  if new.type = 'safety_concern' then
    new.urgency := 'critical';
    new.escalation_level := 3;
  elsif new.about_staff_member is not null then
    new.escalation_level := 3;      -- complaint about a named staff member goes straight to the manager
  else
    new.escalation_level := 1;
  end if;

  select * into d from public.cka_deadlines(new.urgency, new.created_at);
  new.acknowledge_by := d.acknowledge_by;
  new.resolve_by := d.resolve_by;
  return new;
end $$;
create trigger submissions_before_insert before insert on public.submissions
  for each row execute function public.cka_submission_before_insert();

create function public.cka_submission_before_update() returns trigger
language plpgsql as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  d record;
begin
  -- What the parent wrote can never be edited afterwards.
  if new.parent_id is distinct from old.parent_id or new.child_id is distinct from old.child_id
     or new.type is distinct from old.type or new.title is distinct from old.title
     or new.description is distinct from old.description or new.created_at is distinct from old.created_at
     or new.ref_no is distinct from old.ref_no then
    raise exception 'The original submission cannot be edited';
  end if;

  new.updated_at := now();

  -- A safety concern stays critical.
  if new.type = 'safety_concern' and new.urgency <> 'critical' then
    raise exception 'Safety concerns are always critical';
  end if;

  -- Changing urgency needs a reason (the parent sees it). The system (no logged-in user) is exempt.
  if new.urgency is distinct from old.urgency then
    if auth.uid() is not null and reason is null then
      raise exception 'A reason is required when changing urgency';
    end if;
    select * into d from public.cka_deadlines(new.urgency, now());
    new.acknowledge_by := case when old.acknowledged_at is null then d.acknowledge_by else new.acknowledge_by end;
    new.resolve_by := d.resolve_by;
  end if;

  if new.status in ('acknowledged', 'in_progress', 'resolved', 'closed') and new.acknowledged_at is null then
    new.acknowledged_at := now();
  end if;
  if new.status = 'resolved' and old.status <> 'resolved' then new.resolved_at := now(); end if;
  if new.status in ('received', 'acknowledged', 'in_progress') then new.resolved_at := null; end if;
  return new;
end $$;
create trigger submissions_before_update before update on public.submissions
  for each row execute function public.cka_submission_before_update();

create function public.cka_actor_name() returns text
language sql stable security definer set search_path = public as $$
  select full_name from public.profiles where id = auth.uid()
$$;

create function public.cka_person_name(p_id uuid) returns text
language sql stable security definer set search_path = public as $$
  select full_name from public.profiles where id = p_id
$$;

create function public.cka_submission_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
  values (new.id, new.parent_id, public.cka_person_name(new.parent_id), 'created', 'Submission received',
          new.urgency, true);
  return new;
end $$;
create trigger submissions_after_insert after insert on public.submissions
  for each row execute function public.cka_submission_after_insert();

-- Every status, urgency, assignment or escalation change writes a timeline row.
create function public.cka_submission_after_update() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  who uuid := auth.uid();
  who_name text := public.cka_actor_name();
begin
  if new.status is distinct from old.status then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name,
            case new.status when 'acknowledged' then 'acknowledged' when 'resolved' then 'resolved' else 'status_changed' end,
            reason, old.status, new.status, true);
  end if;
  if new.urgency is distinct from old.urgency then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'urgency_changed', reason, old.urgency, new.urgency, true);
  end if;
  if new.assigned_to is distinct from old.assigned_to then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'assigned', 'Assigned to ' || coalesce(public.cka_person_name(new.assigned_to), 'nobody'),
            old.assigned_to::text, new.assigned_to::text, true);
  end if;
  if new.escalation_level is distinct from old.escalation_level then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, old_value, new_value, visible_to_parent)
    values (new.id, who, who_name, 'escalated', coalesce(reason, 'Escalation level changed'),
            old.escalation_level::text, new.escalation_level::text, false);   -- escalation is internal
  end if;
  return new;
end $$;
create trigger submissions_after_update after update on public.submissions
  for each row execute function public.cka_submission_after_update();

-- Events are a permanent record: fill in who/when, never edit or delete.
create function public.cka_event_before_insert() returns trigger
language plpgsql as $$
begin
  if auth.uid() is not null then
    new.actor_id := auth.uid();
    new.actor_name := public.cka_actor_name();
  end if;
  new.created_at := now();
  return new;
end $$;
create trigger submission_events_before_insert before insert on public.submission_events
  for each row execute function public.cka_event_before_insert();

create function public.cka_event_immutable() returns trigger
language plpgsql as $$
begin raise exception 'Timeline events cannot be changed or deleted'; end $$;
create trigger submission_events_no_update before update or delete on public.submission_events
  for each row execute function public.cka_event_immutable();

-- ---------------------------------------------------------------------------
-- Ratings: the class is taken from the child, never from the client
-- ---------------------------------------------------------------------------
create function public.cka_rating_before_insert() returns trigger
language plpgsql as $$
begin
  new.parent_id := coalesce(auth.uid(), new.parent_id);
  new.class_id := (select class_id from public.children where id = new.child_id);
  new.month := (date_trunc('month', now() at time zone 'Africa/Cairo'))::date;
  new.created_at := now();
  return new;
end $$;
create trigger ratings_before_insert before insert on public.ratings
  for each row execute function public.cka_rating_before_insert();

-- ---------------------------------------------------------------------------
-- Investigations: steps in order, no skipping, closing needs findings + actions
-- ---------------------------------------------------------------------------
create function public.cka_investigation_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.investigation_steps (investigation_id, step, completed_by) values (new.id, 'opened', auth.uid());
  insert into public.investigation_internal (investigation_id) values (new.id);
  return new;
end $$;
create trigger investigations_after_insert after insert on public.investigations
  for each row execute function public.cka_investigation_after_insert();

create function public.cka_step_before_insert() returns trigger
language plpgsql as $$
declare
  order_ text[] := array['opened', 'parent_called', 'facts_gathered', 'findings', 'actions_taken', 'parent_informed', 'closed'];
  idx int := array_position(order_, new.step);
  done int := (select count(*) from public.investigation_steps where investigation_id = new.investigation_id);
begin
  if idx is distinct from done + 1 then
    raise exception 'Investigation steps cannot be skipped: next step is %', order_[done + 1];
  end if;
  new.completed_by := coalesce(auth.uid(), new.completed_by);
  new.completed_at := now();

  if new.step = 'findings' and coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = '' then
    raise exception 'Write the findings for the parent before completing the findings step';
  end if;
  if new.step = 'closed' then
    if coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = ''
       or coalesce(btrim((select actions_taken from public.investigation_internal where investigation_id = new.investigation_id)), '') = '' then
      raise exception 'Closing requires findings for the parent and actions taken';
    end if;
  end if;
  return new;
end $$;
create trigger investigation_steps_before_insert before insert on public.investigation_steps
  for each row execute function public.cka_step_before_insert();

create function public.cka_step_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare sub uuid;
begin
  if new.step = 'closed' then
    update public.investigations set status = 'closed', closed_at = now() where id = new.investigation_id;
  end if;
  -- Parents see step names and dates on the case timeline.
  select submission_id into sub from public.investigations where id = new.investigation_id;
  if sub is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (sub, new.completed_by, public.cka_person_name(new.completed_by), 'investigation_step', null, new.step, true);
  end if;
  return new;
end $$;
create trigger investigation_steps_after_insert after insert on public.investigation_steps
  for each row execute function public.cka_step_after_insert();

create function public.cka_steps_immutable() returns trigger
language plpgsql as $$
begin raise exception 'Investigation steps cannot be changed or deleted'; end $$;
create trigger investigation_steps_no_change before update or delete on public.investigation_steps
  for each row execute function public.cka_steps_immutable();

create trigger investigation_internal_touch before update on public.investigation_internal
  for each row execute function public.cka_touch_updated_at();

-- ---------------------------------------------------------------------------
-- Actions that need a rule bigger than "can this user update this row"
-- ---------------------------------------------------------------------------

-- Staff: change urgency, with a reason the parent will see.
create function public.change_urgency(p_submission uuid, p_urgency text, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.staff_can_see_submission(p_submission) then raise exception 'Not allowed'; end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'A reason is required'; end if;
  perform set_config('app.change_reason', p_reason, true);
  update public.submissions set urgency = p_urgency where id = p_submission;
end $$;

-- Parent: "Are you satisfied with how this was handled?"  Yes closes it; No reopens it
-- and moves it up one escalation level.
create function public.respond_to_resolution(p_submission uuid, p_satisfied boolean) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions;
begin
  select * into s from public.submissions where id = p_submission;
  if s.id is null or not public.owns_submission(p_submission) then raise exception 'Not allowed'; end if;
  if s.status <> 'resolved' then raise exception 'This submission has not been resolved yet'; end if;

  if p_satisfied then
    update public.submissions set status = 'closed', parent_satisfied = true where id = p_submission;
    insert into public.submission_events (submission_id, event_type, message, visible_to_parent)
    values (p_submission, 'satisfaction', 'Parent confirmed they are satisfied', true);
  else
    perform set_config('app.change_reason', 'Parent was not satisfied; reopened', true);
    update public.submissions
       set status = 'in_progress', parent_satisfied = false, escalation_level = least(escalation_level + 1, 4)
     where id = p_submission;
    insert into public.submission_events (submission_id, event_type, message, visible_to_parent)
    values (p_submission, 'reopened', 'Parent was not satisfied; case reopened', true);
  end if;
end $$;

-- Parent: "I've read this report" on an accident report. Records the time once.
create function public.mark_incident_read(p_incident uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() <> 'parent'
     or not public.can_see_child((select child_id from public.incidents where id = p_incident)) then
    raise exception 'Not allowed';
  end if;
  update public.incidents set parent_signed_at = now() where id = p_incident and parent_signed_at is null;
end $$;

-- Parent: acknowledge an investigation outcome, or disagree (which escalates a linked case to the owner).
create function public.respond_to_investigation(p_investigation uuid, p_response text) returns void
language plpgsql security definer set search_path = public as $$
declare inv public.investigations;
begin
  if p_response not in ('acknowledged', 'disagreed') then raise exception 'Invalid response'; end if;
  select * into inv from public.investigations where id = p_investigation;
  if inv.id is null or not public.parent_owns_investigation(p_investigation) then raise exception 'Not allowed'; end if;
  if coalesce(btrim(inv.findings_for_parent), '') = '' then raise exception 'There are no findings to respond to yet'; end if;

  update public.investigations set parent_response = p_response, parent_responded_at = now() where id = p_investigation;
  if p_response = 'disagreed' and inv.submission_id is not null then
    perform set_config('app.change_reason', 'Parent disagrees with the investigation outcome', true);
    update public.submissions set escalation_level = 4 where id = inv.submission_id;
  end if;
end $$;

revoke all on function
  public.change_urgency(uuid, text, text), public.respond_to_resolution(uuid, boolean),
  public.mark_incident_read(uuid), public.respond_to_investigation(uuid, text),
  public.cka_person_name(uuid)
from public;
grant execute on function
  public.change_urgency(uuid, text, text), public.respond_to_resolution(uuid, boolean),
  public.mark_incident_read(uuid), public.respond_to_investigation(uuid, text)
to authenticated;

-- ============================================================
-- migrations/20261006120400_row_level_security.sql
-- ============================================================
-- Row-level security (Prompt 3). Privacy lives here, in the database, not in the screens.
-- Default is "no access": a table with RLS on and no matching policy returns nothing.
-- Deactivated users have auth_role() = NULL, so every policy below refuses them.

alter table public.profiles               enable row level security;
alter table public.classes                enable row level security;
alter table public.children               enable row level security;
alter table public.parent_children        enable row level security;
alter table public.staff_classes          enable row level security;
alter table public.submissions            enable row level security;
alter table public.submission_events      enable row level security;
alter table public.incidents              enable row level security;
alter table public.investigations         enable row level security;
alter table public.investigation_internal enable row level security;
alter table public.investigation_steps    enable row level security;
alter table public.ratings                enable row level security;
alter table public.attachments            enable row level security;

-- Start from nothing; grant only what the policies need.
revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

grant select on public.profiles, public.classes, public.children, public.parent_children, public.staff_classes,
                public.submissions, public.submission_events, public.incidents, public.investigations,
                public.investigation_internal, public.investigation_steps, public.ratings, public.attachments
  to authenticated;
grant insert on public.submissions, public.submission_events, public.incidents, public.investigation_steps,
                public.investigations, public.ratings, public.attachments,
                public.children, public.classes, public.parent_children, public.staff_classes
  to authenticated;
grant update on public.submissions, public.incidents, public.investigations, public.investigation_internal,
                public.children, public.classes
  to authenticated;
-- Users may edit only these three fields of their own profile. Roles and active flags are
-- changed only by the server (Prompt 4) using the service key.
grant update (full_name, phone, language) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
create policy profiles_self        on public.profiles for select using (id = auth.uid() and public.auth_role() is not null);
create policy profiles_management  on public.profiles for select using (public.is_management());
create policy profiles_teacher     on public.profiles for select using (public.teacher_sees_parent(id));
create policy profiles_update_self on public.profiles for update
  using (id = auth.uid() and public.auth_role() is not null) with check (id = auth.uid());

-- ---------------------------------------------------------------------------
-- classes, children, links
-- ---------------------------------------------------------------------------
create policy classes_management on public.classes for select using (public.is_management());
create policy classes_teacher    on public.classes for select using (public.teaches_class(id));
create policy classes_parent     on public.classes for select using (
  public.auth_role() = 'parent' and exists (
    select 1 from public.children c where c.class_id = classes.id and public.can_see_child(c.id)));
create policy classes_write      on public.classes for insert with check (public.is_management());
create policy classes_update     on public.classes for update using (public.is_management()) with check (public.is_management());

create policy children_select on public.children for select using (public.can_see_child(id));
create policy children_insert on public.children for insert with check (public.is_management());
create policy children_update on public.children for update using (public.is_management()) with check (public.is_management());

create policy parent_children_own        on public.parent_children for select
  using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy parent_children_management on public.parent_children for select using (public.is_management());
create policy parent_children_insert     on public.parent_children for insert with check (public.is_management());

create policy staff_classes_own        on public.staff_classes for select using (staff_id = auth.uid() and public.auth_role() is not null);
create policy staff_classes_management on public.staff_classes for select using (public.is_management());
create policy staff_classes_insert     on public.staff_classes for insert with check (public.is_management());

-- ---------------------------------------------------------------------------
-- submissions
-- ---------------------------------------------------------------------------
create policy submissions_parent_select on public.submissions for select
  using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy submissions_staff_select  on public.submissions for select
  using (public.staff_can_see_submission(id));
create policy submissions_parent_insert on public.submissions for insert
  with check (public.auth_role() = 'parent' and parent_id = auth.uid() and public.can_see_child(child_id)
              and type in ('complaint', 'safety_concern'));
create policy submissions_staff_update  on public.submissions for update
  using (public.staff_can_see_submission(id)) with check (public.staff_can_see_submission(id));
-- Parents have no UPDATE policy: they act through respond_to_resolution().

-- ---------------------------------------------------------------------------
-- submission_events
-- ---------------------------------------------------------------------------
create policy events_parent_select on public.submission_events for select
  using (visible_to_parent and public.owns_submission(submission_id));
create policy events_staff_select  on public.submission_events for select
  using (public.staff_can_see_submission(submission_id));
create policy events_parent_insert on public.submission_events for insert
  with check (event_type = 'parent_reply' and visible_to_parent and actor_id = auth.uid()
              and public.owns_submission(submission_id));
create policy events_staff_insert  on public.submission_events for insert
  with check (actor_id = auth.uid() and event_type in ('update', 'internal_note')
              and (visible_to_parent = (event_type = 'update'))
              and public.staff_can_see_submission(submission_id));

-- ---------------------------------------------------------------------------
-- incidents (staff log them; parents read their own child's)
-- ---------------------------------------------------------------------------
create policy incidents_select on public.incidents for select using (public.can_see_child(child_id));
create policy incidents_insert on public.incidents for insert
  with check (public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
              and reported_by = auth.uid() and public.can_see_child(child_id));
create policy incidents_update on public.incidents for update
  using (public.is_management()) with check (public.is_management());

-- ---------------------------------------------------------------------------
-- investigations
--   parents:       the shared part of their own, only
--   admin:         the shared part, never internal findings
--   manager/owner: everything
--   teachers:      nothing
-- ---------------------------------------------------------------------------
create policy investigations_parent     on public.investigations for select using (public.parent_owns_investigation(id));
create policy investigations_management on public.investigations for select using (public.is_management());
create policy investigations_insert     on public.investigations for insert with check (public.is_manager_or_owner());
create policy investigations_update     on public.investigations for update
  using (public.is_manager_or_owner()) with check (public.is_manager_or_owner());

create policy investigation_internal_select on public.investigation_internal for select using (public.is_manager_or_owner());
create policy investigation_internal_update on public.investigation_internal for update
  using (public.is_manager_or_owner()) with check (public.is_manager_or_owner());

create policy steps_parent     on public.investigation_steps for select using (public.parent_owns_investigation(investigation_id));
create policy steps_management on public.investigation_steps for select using (public.is_management());
create policy steps_insert     on public.investigation_steps for insert with check (public.is_manager_or_owner());

-- ---------------------------------------------------------------------------
-- ratings: a parent writes (and re-reads) their own; only manager and owner read the rest
-- ---------------------------------------------------------------------------
create policy ratings_own        on public.ratings for select using (public.auth_role() = 'parent' and parent_id = auth.uid());
create policy ratings_management on public.ratings for select using (public.is_manager_or_owner());
create policy ratings_insert     on public.ratings for insert
  with check (public.auth_role() = 'parent' and parent_id = auth.uid() and public.can_see_child(child_id));

-- ---------------------------------------------------------------------------
-- attachments (metadata; the files are in the private storage bucket)
-- ---------------------------------------------------------------------------
create policy attachments_parent_select on public.attachments for select using (public.owns_submission(submission_id));
create policy attachments_staff_select  on public.attachments for select using (public.staff_can_see_submission(submission_id));
create policy attachments_insert        on public.attachments for insert
  with check (uploaded_by = auth.uid()
              and (public.owns_submission(submission_id) or public.staff_can_see_submission(submission_id))
              and storage_path like submission_id::text || '/%');

-- ============================================================
-- migrations/20261006120500_storage.sql
-- ============================================================
-- Private photo storage (Prompt 3). Files are never public; the app asks for short-lived
-- signed links. Images only, 5 MB maximum. File path convention: "<submission_id>/<file name>".

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('attachments', 'attachments', false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
on conflict (id) do update
  set public = false, file_size_limit = 5242880,
      allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/heic'];

create policy attachments_bucket_read on storage.objects for select to authenticated
  using (bucket_id = 'attachments' and (
    public.owns_submission(((storage.foldername(name))[1])::uuid)
    or public.staff_can_see_submission(((storage.foldername(name))[1])::uuid)));

create policy attachments_bucket_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'attachments' and (
    public.owns_submission(((storage.foldername(name))[1])::uuid)
    or public.staff_can_see_submission(((storage.foldername(name))[1])::uuid)));
-- No update or delete policies: uploaded evidence cannot be changed by users.

-- ============================================================
-- migrations/20261006120600_parent_views.sql
-- ============================================================
-- Narrow, parent-safe lookups for the parent portal (Prompt 5).
-- Parents cannot read other people's profiles, so anything that needs a staff name goes
-- through these functions. Each returns only what a parent may see, and only their own data.

-- The parent's own cases, with the name of whoever is handling each (no escalation level,
-- no internal fields).
create function public.parent_cases()
returns table (
  id uuid, ref_no bigint, type text, title text, urgency text, status text,
  created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  parent_satisfied boolean, handler_name text
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.urgency, s.status,
         s.created_at, s.acknowledge_by, s.resolve_by, s.parent_satisfied, p.full_name
  from public.submissions s
  left join public.profiles p on p.id = s.assigned_to
  where public.auth_role() = 'parent' and s.parent_id = auth.uid()
  order by s.created_at desc
$$;

-- Accident reports about the parent's own children, with the reporting staff member's name.
create function public.parent_incidents()
returns table (
  id uuid, child_id uuid, child_name text, occurred_at timestamptz, location text,
  what_happened text, injury text, first_aid text, severity text,
  parent_called_at timestamptz, parent_signed_at timestamptz, reported_by_name text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.child_id, c.full_name, i.occurred_at, i.location,
         i.what_happened, i.injury, i.first_aid, i.severity,
         i.parent_called_at, i.parent_signed_at, p.full_name
  from public.incidents i
  join public.children c on c.id = i.child_id
  left join public.profiles p on p.id = i.reported_by
  where public.auth_role() = 'parent' and public.can_see_child(i.child_id)
  order by i.occurred_at desc
$$;

-- Names (only) of active staff, so a parent can say a concern or a compliment is about someone.
-- Parents only; no phone, email or role is returned.
create function public.list_staff_names()
returns table (id uuid, full_name text)
language sql stable security definer set search_path = public as $$
  select p.id, p.full_name
  from public.profiles p
  where public.auth_role() = 'parent' and p.active and p.role in ('teacher', 'admin', 'manager')
  order by p.full_name
$$;

revoke all on function public.parent_cases(), public.parent_incidents(), public.list_staff_names() from public;
grant execute on function public.parent_cases(), public.parent_incidents(), public.list_staff_names() to authenticated;

-- ============================================================
-- migrations/20261006120700_staff_tools.sql
-- ============================================================
-- Staff dashboard support (Prompt 6): the work queue, case details, and the actions staff take
-- on a case. Every action goes through a function so the rules (who may act, reasons required,
-- timeline entry written) cannot be skipped from the browser.

-- ---------------------------------------------------------------------------
-- Teachers never see a complaint that names a staff member (it goes to the manager).
-- This is stricter than "except complaints about themselves": a teacher should not
-- read a complaint about a colleague either.
-- ---------------------------------------------------------------------------
create or replace function public.staff_can_see_submission(p_submission uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when public.is_management() then exists (select 1 from public.submissions s where s.id = p_submission)
    when public.auth_role() = 'teacher' then exists (
      select 1 from public.submissions s
      where s.id = p_submission
        and s.about_staff_member is null
        and public.can_see_child(s.child_id))
    else false
  end
$$;

-- ---------------------------------------------------------------------------
-- Who handles a case at each escalation level
--   level 2: the head teacher of the child's class (never the person complained about)
--   level 3: an active manager      level 4: an active owner
-- ---------------------------------------------------------------------------
create function public.cka_level_assignee(p_level int, p_child uuid, p_subject uuid) returns uuid
language sql stable security definer set search_path = public as $$
  select case
    when p_level = 2 then (
      select cl.head_teacher_id from public.children c join public.classes cl on cl.id = c.class_id
      join public.profiles h on h.id = cl.head_teacher_id and h.active
      where c.id = p_child and cl.head_teacher_id is distinct from p_subject)
    when p_level = 3 then (select p.id from public.profiles p where p.role = 'manager' and p.active
                           and p.id is distinct from p_subject order by p.created_at limit 1)
    when p_level = 4 then (select p.id from public.profiles p where p.role = 'owner' and p.active
                           and p.id is distinct from p_subject order by p.created_at limit 1)
  end
$$;
revoke all on function public.cka_level_assignee(int, uuid, uuid) from public;

-- New cases that start at level 3 (safety concerns, complaints about staff) go straight to a manager.
create function public.cka_submission_autoassign() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.assigned_to is null and new.escalation_level >= 3 then
    new.assigned_to := public.cka_level_assignee(new.escalation_level, new.child_id, new.about_staff_member);
  end if;
  return new;
end $$;
create trigger submissions_before_insert_assign before insert on public.submissions
  for each row execute function public.cka_submission_autoassign();

create or replace function public.cka_submission_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
  values (new.id, new.parent_id, public.cka_person_name(new.parent_id), 'created', 'Submission received', new.urgency, true);
  if new.assigned_to is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (new.id, null, null, 'assigned', 'Assigned to ' || public.cka_person_name(new.assigned_to), new.assigned_to::text, true);
  end if;
  return new;
end $$;

-- A serious accident opens a safety investigation, assigned to a manager (Prompt 21).
create function public.cka_incident_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.severity = 'serious' then
    insert into public.investigations (incident_id, submission_id, assigned_to)
    values (new.id, new.submission_id, public.cka_level_assignee(3, new.child_id, null))
    on conflict do nothing;
  end if;
  return new;
end $$;
create trigger incidents_after_insert after insert on public.incidents
  for each row execute function public.cka_incident_after_insert();

-- ---------------------------------------------------------------------------
-- Reading: queue, one case, staff list, ratings
-- ---------------------------------------------------------------------------
create function public.staff_queue(p_include_done boolean default true)
returns table (
  id uuid, ref_no bigint, type text, title text, urgency text, status text, escalation_level smallint,
  created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, next_due timestamptz,
  child_id uuid, child_name text, class_id uuid, class_name text, parent_name text,
  assigned_to uuid, assignee_name text, about_staff_name text
)
language sql stable security definer set search_path = public as $$
  select q.* from (
    select s.id, s.ref_no, s.type, s.title, s.urgency, s.status, s.escalation_level,
           s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at,
           case when s.status = 'received' then s.acknowledge_by
                when s.status in ('acknowledged', 'in_progress') then s.resolve_by end as next_due,
           s.child_id, c.full_name, c.class_id, cl.name, pp.full_name,
           s.assigned_to, a.full_name,
           case when public.is_management() then ab.full_name end
    from public.submissions s
    join public.children c on c.id = s.child_id
    left join public.classes cl on cl.id = c.class_id
    join public.profiles pp on pp.id = s.parent_id
    left join public.profiles a on a.id = s.assigned_to
    left join public.profiles ab on ab.id = s.about_staff_member
    where public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
      and public.staff_can_see_submission(s.id)
      and (p_include_done or s.status not in ('resolved', 'closed'))
  ) q
  order by (case when q.status in ('resolved', 'closed') then 1 else 0 end), q.next_due nulls last, q.created_at
$$;

create function public.staff_case(p_id uuid)
returns table (
  id uuid, ref_no bigint, type text, title text, description text, urgency text, status text,
  escalation_level smallint, created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, parent_satisfied boolean,
  child_id uuid, child_name text, class_name text, parent_name text, parent_phone text,
  assigned_to uuid, assignee_name text, about_staff_name text, has_investigation boolean
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.description, s.urgency, s.status, s.escalation_level,
         s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at, s.parent_satisfied,
         s.child_id, c.full_name, cl.name, pp.full_name, pp.phone,
         s.assigned_to, a.full_name,
         case when public.is_management() then ab.full_name end,
         public.is_management() and exists (select 1 from public.investigations i where i.submission_id = s.id)
  from public.submissions s
  join public.children c on c.id = s.child_id
  left join public.classes cl on cl.id = c.class_id
  join public.profiles pp on pp.id = s.parent_id
  left join public.profiles a on a.id = s.assigned_to
  left join public.profiles ab on ab.id = s.about_staff_member
  where s.id = p_id and public.staff_can_see_submission(s.id)
$$;

-- Active staff (names and roles) for assigning cases.
create function public.staff_list()
returns table (id uuid, full_name text, role text)
language sql stable security definer set search_path = public as $$
  select p.id, p.full_name, p.role from public.profiles p
  where public.auth_role() in ('teacher', 'admin', 'manager', 'owner')
    and p.active and p.role in ('teacher', 'admin', 'manager', 'owner')
  order by p.full_name
$$;

-- Ratings and compliments: manager and owner only.
create function public.staff_ratings()
returns table (
  id uuid, month date, class_name text, child_name text, care_score smallint, communication_score smallint,
  daily_reports_score smallint, comment text, compliment_staff_name text, compliment_text text, created_at timestamptz
)
language sql stable security definer set search_path = public as $$
  select r.id, r.month, cl.name, c.full_name, r.care_score, r.communication_score, r.daily_reports_score,
         r.comment, st.full_name, r.compliment_text, r.created_at
  from public.ratings r
  join public.children c on c.id = r.child_id
  left join public.classes cl on cl.id = r.class_id
  left join public.profiles st on st.id = r.compliment_staff_id
  where public.is_manager_or_owner()
  order by r.created_at desc
$$;

-- ---------------------------------------------------------------------------
-- Actions (each writes a timeline entry through the submission triggers)
-- ---------------------------------------------------------------------------
create function public.cka_require_staff_case(p_submission uuid) returns public.submissions
language plpgsql stable security definer set search_path = public as $$
declare s public.submissions;
begin
  if public.auth_role() not in ('teacher', 'admin', 'manager', 'owner') or not public.staff_can_see_submission(p_submission) then
    raise exception 'Not allowed';
  end if;
  select * into s from public.submissions where id = p_submission;
  return s;
end $$;

-- Acknowledge: records the time and sends the parent a message (visible on their timeline).
create function public.staff_acknowledge(p_submission uuid, p_message text default null) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status <> 'received' then raise exception 'This case has already been acknowledged'; end if;
  perform set_config('app.change_reason', coalesce(nullif(btrim(p_message), ''), ''), true);
  update public.submissions set status = 'acknowledged' where id = p_submission;
end $$;

create function public.staff_mark_in_progress(p_submission uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status not in ('received', 'acknowledged') then raise exception 'Only a new or acknowledged case can be started'; end if;
  update public.submissions set status = 'in_progress' where id = p_submission;
end $$;

create function public.staff_assign(p_submission uuid, p_staff uuid) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if s.status in ('resolved', 'closed') then raise exception 'This case is finished'; end if;
  if not exists (select 1 from public.profiles where id = p_staff and active and role in ('teacher', 'admin', 'manager', 'owner')) then
    raise exception 'Choose an active staff member';
  end if;
  if p_staff = s.about_staff_member then raise exception 'A complaint cannot be assigned to the person it is about'; end if;
  update public.submissions set assigned_to = p_staff where id = p_submission;
end $$;

-- Escalate one level, with a reason, and hand it to the person for that level.
create function public.staff_escalate(p_submission uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission); nxt int; who uuid;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'A reason is required'; end if;
  if s.status in ('resolved', 'closed') then raise exception 'This case is finished'; end if;
  if s.escalation_level >= 4 then raise exception 'Already at the highest level'; end if;
  nxt := s.escalation_level + 1;
  who := public.cka_level_assignee(nxt, s.child_id, s.about_staff_member);
  perform set_config('app.change_reason', p_reason, true);
  update public.submissions set escalation_level = nxt, assigned_to = coalesce(who, s.assigned_to) where id = p_submission;
end $$;

-- Resolve with a message for the parent.
create function public.staff_resolve(p_submission uuid, p_message text) returns void
language plpgsql security definer set search_path = public as $$
declare s public.submissions := public.cka_require_staff_case(p_submission);
begin
  if nullif(btrim(coalesce(p_message, '')), '') is null then raise exception 'A message for the parent is required'; end if;
  if s.status in ('resolved', 'closed') then raise exception 'This case is already finished'; end if;
  perform set_config('app.change_reason', p_message, true);
  update public.submissions set status = 'resolved' where id = p_submission;
end $$;

-- Grants: callable by logged-in users; each function checks the role itself.
revoke all on function
  public.staff_queue(boolean), public.staff_case(uuid), public.staff_list(), public.staff_ratings(),
  public.cka_require_staff_case(uuid), public.staff_acknowledge(uuid, text), public.staff_mark_in_progress(uuid),
  public.staff_assign(uuid, uuid), public.staff_escalate(uuid, text), public.staff_resolve(uuid, text)
from public;
grant execute on function
  public.staff_queue(boolean), public.staff_case(uuid), public.staff_list(), public.staff_ratings(),
  public.staff_acknowledge(uuid, text), public.staff_mark_in_progress(uuid),
  public.staff_assign(uuid, uuid), public.staff_escalate(uuid, text), public.staff_resolve(uuid, text)
to authenticated;

-- ============================================================
-- migrations/20261006120800_investigations.sql
-- ============================================================
-- Investigation workflow (Prompt 7).
--   * A safety concern opens an investigation automatically, assigned to a manager.
--   * Findings for the parent are WRITTEN as a draft (manager/owner only) and only become visible
--     to the parent when the "findings" step is completed, so a half-written draft never leaks.
--   * A warning function spots other children's names in the findings before they are published.
--   * Manager/owner list and detail functions, including how long each investigation took.

-- ---------------------------------------------------------------------------
-- Draft findings live with the internal (manager/owner-only) data
-- ---------------------------------------------------------------------------
alter table public.investigation_internal add column findings_draft text;

-- Edits go through save_investigation() (below), not direct table updates.
revoke update on public.investigations, public.investigation_internal from authenticated;
grant update (assigned_to) on public.investigations to authenticated;

-- ---------------------------------------------------------------------------
-- "Opened" step: record the manager/owner who opened it, or nobody (the system) when it
-- opened automatically from a parent's submission or a teacher's accident report.
-- ---------------------------------------------------------------------------
create or replace function public.cka_investigation_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.investigation_steps (investigation_id, step, completed_by)
  values (new.id, 'opened', case when public.auth_role() in ('manager', 'owner') then auth.uid() end);
  insert into public.investigation_internal (investigation_id) values (new.id);
  return new;
end $$;

-- A safety concern opens an investigation, assigned to a manager.
create function public.cka_submission_open_investigation() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.type = 'safety_concern' then
    insert into public.investigations (submission_id, assigned_to)
    values (new.id, public.cka_level_assignee(3, new.child_id, new.about_staff_member))
    on conflict do nothing;
  end if;
  return new;
end $$;
create trigger submissions_after_insert_investigation after insert on public.submissions
  for each row execute function public.cka_submission_open_investigation();

-- ---------------------------------------------------------------------------
-- Steps: in order, never skipped. "Findings" needs something to publish; "closed" needs the
-- published findings AND the actions taken. Completing "findings" publishes the draft.
-- ---------------------------------------------------------------------------
create or replace function public.cka_step_before_insert() returns trigger
language plpgsql as $$
declare
  order_ text[] := array['opened', 'parent_called', 'facts_gathered', 'findings', 'actions_taken', 'parent_informed', 'closed'];
  idx int := array_position(order_, new.step);
  done int := (select count(*) from public.investigation_steps where investigation_id = new.investigation_id);
begin
  if idx is distinct from done + 1 then
    raise exception 'Investigation steps cannot be skipped: next step is %', order_[done + 1];
  end if;
  -- Credit the manager/owner completing the step. A step recorded while a parent or teacher is
  -- logged in (the automatic "opened" step) is credited to the system, never to them.
  new.completed_by := case when public.auth_role() in ('manager', 'owner') then auth.uid() else new.completed_by end;
  new.completed_at := now();

  if new.step = 'findings' and
     coalesce(nullif(btrim((select findings_draft from public.investigation_internal where investigation_id = new.investigation_id)), ''),
              nullif(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '')) is null then
    raise exception 'Write the findings for the parent before completing the findings step';
  end if;
  if new.step = 'closed' then
    if coalesce(btrim((select findings_for_parent from public.investigations where id = new.investigation_id)), '') = ''
       or coalesce(btrim((select actions_taken from public.investigation_internal where investigation_id = new.investigation_id)), '') = '' then
      raise exception 'Closing requires findings for the parent and actions taken';
    end if;
  end if;
  return new;
end $$;

create or replace function public.cka_step_after_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare sub uuid;
begin
  if new.step = 'findings' then
    update public.investigations i
       set findings_for_parent = coalesce(
             nullif(btrim((select d.findings_draft from public.investigation_internal d where d.investigation_id = i.id)), ''),
             i.findings_for_parent)
     where i.id = new.investigation_id;
  end if;
  if new.step = 'closed' then
    update public.investigations set status = 'closed', closed_at = now() where id = new.investigation_id;
  end if;
  select submission_id into sub from public.investigations where id = new.investigation_id;
  if sub is not null then
    insert into public.submission_events (submission_id, actor_id, actor_name, event_type, message, new_value, visible_to_parent)
    values (sub, new.completed_by, public.cka_person_name(new.completed_by), 'investigation_step', null, new.step, true);
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- Writing the investigation (manager / owner)
-- ---------------------------------------------------------------------------
create function public.save_investigation(p_id uuid, p_findings text, p_internal text, p_statements text, p_actions text)
returns void language plpgsql security definer set search_path = public as $$
declare inv public.investigations; published boolean;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  select * into inv from public.investigations where id = p_id;
  if inv.id is null then raise exception 'Not found'; end if;
  if inv.status = 'closed' then raise exception 'This investigation is closed and can no longer be changed'; end if;
  published := exists (select 1 from public.investigation_steps where investigation_id = p_id and step = 'findings');
  if published and nullif(btrim(coalesce(p_findings, '')), '') is null then
    raise exception 'The findings for the parent have been shared, so they cannot be left empty';
  end if;
  update public.investigation_internal
     set findings_draft = p_findings, internal_findings = p_internal, staff_statements = p_statements, actions_taken = p_actions
   where investigation_id = p_id;
  if published then
    update public.investigations set findings_for_parent = p_findings where id = p_id;   -- keep the shared text in step
  end if;
end $$;

-- Names of OTHER children found in a text. The family's own children are excluded.
-- Matches the full name or the first name (3+ letters) as a whole word; a "(seed)" test suffix is ignored.
create function public.investigation_name_warnings(p_id uuid, p_text text) returns setof text
language plpgsql stable security definer set search_path = public as $$
declare norm text;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  norm := ' ' || regexp_replace(lower(coalesce(p_text, '')), '[\s.,;:!?"''()\[\]{}/\\-]+|[،؛؟]+', ' ', 'g') || ' ';
  return query
  with inv as (
    select coalesce(s.child_id, n.child_id) as case_child
    from public.investigations i
    left join public.submissions s on s.id = i.submission_id
    left join public.incidents n on n.id = i.incident_id
    where i.id = p_id),
  own as (
    select inv.case_child as child_id from inv
    union
    select pc2.child_id from inv
      join public.parent_children pc on pc.child_id = inv.case_child
      join public.parent_children pc2 on pc2.parent_id = pc.parent_id),
  cand as (
    select btrim(regexp_replace(c.full_name, '\s*\(seed\)\s*$', '', 'i')) as clean
    from public.children c where c.id not in (select child_id from own))
  select distinct cand.clean from cand
  where position(' ' || lower(cand.clean) || ' ' in norm) > 0
     or (length(split_part(cand.clean, ' ', 1)) >= 3
         and position(' ' || lower(split_part(cand.clean, ' ', 1)) || ' ' in norm) > 0)
  order by 1;
end $$;

-- ---------------------------------------------------------------------------
-- Reading (manager / owner)
-- ---------------------------------------------------------------------------
create function public.staff_investigations()
returns table (
  id uuid, status text, opened_at timestamptz, closed_at timestamptz, hours_taken numeric,
  steps_done int, current_step text, assigned_name text, parent_response text,
  kind text, ref_no bigint, headline text, child_name text, severity text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.status, i.opened_at, i.closed_at,
         round((extract(epoch from (coalesce(i.closed_at, now()) - i.opened_at)) / 3600)::numeric, 1),
         (select count(*)::int from public.investigation_steps st where st.investigation_id = i.id),
         (select st.step from public.investigation_steps st where st.investigation_id = i.id order by st.completed_at desc, st.id desc limit 1),
         a.full_name, i.parent_response,
         case when i.incident_id is not null then 'accident' else 'safety_concern' end,
         s.ref_no, coalesce(s.title, left(n.what_happened, 80)),
         c.full_name, n.severity
  from public.investigations i
  left join public.submissions s on s.id = i.submission_id
  left join public.incidents n on n.id = i.incident_id
  join public.children c on c.id = coalesce(s.child_id, n.child_id)
  left join public.profiles a on a.id = i.assigned_to
  where public.is_manager_or_owner()
  order by (i.status = 'closed'), i.opened_at desc
$$;

create function public.staff_investigation(p_id uuid)
returns table (
  id uuid, status text, opened_at timestamptz, closed_at timestamptz, hours_taken numeric,
  assigned_name text, parent_response text, parent_responded_at timestamptz,
  findings_for_parent text, findings_draft text, internal_findings text, staff_statements text, actions_taken text,
  kind text, submission_id uuid, ref_no bigint, headline text, description text, child_name text, severity text,
  occurred_at timestamptz, location text
)
language sql stable security definer set search_path = public as $$
  select i.id, i.status, i.opened_at, i.closed_at,
         round((extract(epoch from (coalesce(i.closed_at, now()) - i.opened_at)) / 3600)::numeric, 1),
         a.full_name, i.parent_response, i.parent_responded_at,
         i.findings_for_parent, x.findings_draft, x.internal_findings, x.staff_statements, x.actions_taken,
         case when i.incident_id is not null then 'accident' else 'safety_concern' end,
         i.submission_id, s.ref_no, coalesce(s.title, left(n.what_happened, 80)), coalesce(s.description, n.what_happened),
         c.full_name, n.severity, n.occurred_at, n.location
  from public.investigations i
  join public.investigation_internal x on x.investigation_id = i.id
  left join public.submissions s on s.id = i.submission_id
  left join public.incidents n on n.id = i.incident_id
  join public.children c on c.id = coalesce(s.child_id, n.child_id)
  left join public.profiles a on a.id = i.assigned_to
  where i.id = p_id and public.is_manager_or_owner()
$$;

-- staff_case now also says which investigation belongs to the case (manager/owner only).
drop function public.staff_case(uuid);
create function public.staff_case(p_id uuid)
returns table (
  id uuid, ref_no bigint, type text, title text, description text, urgency text, status text,
  escalation_level smallint, created_at timestamptz, acknowledge_by timestamptz, resolve_by timestamptz,
  acknowledged_at timestamptz, resolved_at timestamptz, parent_satisfied boolean,
  child_id uuid, child_name text, class_name text, parent_name text, parent_phone text,
  assigned_to uuid, assignee_name text, about_staff_name text, has_investigation boolean, investigation_id uuid
)
language sql stable security definer set search_path = public as $$
  select s.id, s.ref_no, s.type, s.title, s.description, s.urgency, s.status, s.escalation_level,
         s.created_at, s.acknowledge_by, s.resolve_by, s.acknowledged_at, s.resolved_at, s.parent_satisfied,
         s.child_id, c.full_name, cl.name, pp.full_name, pp.phone,
         s.assigned_to, a.full_name,
         case when public.is_management() then ab.full_name end,
         public.is_management() and exists (select 1 from public.investigations i where i.submission_id = s.id),
         case when public.is_manager_or_owner() then (select i.id from public.investigations i where i.submission_id = s.id) end
  from public.submissions s
  join public.children c on c.id = s.child_id
  left join public.classes cl on cl.id = c.class_id
  join public.profiles pp on pp.id = s.parent_id
  left join public.profiles a on a.id = s.assigned_to
  left join public.profiles ab on ab.id = s.about_staff_member
  where s.id = p_id and public.staff_can_see_submission(s.id)
$$;

revoke all on function
  public.save_investigation(uuid, text, text, text, text), public.investigation_name_warnings(uuid, text),
  public.staff_investigations(), public.staff_investigation(uuid), public.staff_case(uuid)
from public;
grant execute on function
  public.save_investigation(uuid, text, text, text, text), public.investigation_name_warnings(uuid, text),
  public.staff_investigations(), public.staff_investigation(uuid), public.staff_case(uuid)
to authenticated;

-- ============================================================
-- migrations/20261006120900_notifications.sql
-- ============================================================
-- Notifications and the deadline clock (Prompt 8).
--   * Emails are written to a queue (email_outbox); a Vercel function sends them through Resend.
--   * Deadline checker: warns the assigned person 1 hour before a deadline, and escalates a case
--     one level when a deadline is missed. Non-critical deadlines pause outside working hours
--     (Sunday-Thursday 08:00-18:00 Cairo); critical items are handled at any hour.
--   * Nothing is sent twice for the same deadline.
-- Parent emails are deliberately short: they say there is news and link to the portal, so a
-- child's private details are never sent by email.

alter table public.submissions add column next_escalation_at timestamptz;   -- internal escalation clock

create table public.email_outbox (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid references public.profiles (id),
  to_email    text not null,
  language    text not null check (language in ('ar', 'en')),
  template    text not null,
  payload     jsonb not null default '{}',
  status      text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed')),
  attempts    int not null default 0,
  last_error  text,
  dedupe_key  text unique,
  claimed_at  timestamptz,
  created_at  timestamptz not null default now(),
  sent_at     timestamptz
);
create index email_outbox_pending_idx on public.email_outbox (created_at) where status = 'pending';

create table public.deadline_events (
  id            uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.submissions (id),
  kind          text not null check (kind in ('ack', 'resolve')),
  deadline      timestamptz not null,
  action        text not null check (action in ('warned', 'escalated', 'top')),
  level         smallint not null default 0,
  created_at    timestamptz not null default now(),
  unique (submission_id, kind, deadline, action, level)
);

-- Only the server (service key) touches these.
alter table public.email_outbox enable row level security;
alter table public.deadline_events enable row level security;
revoke all on public.email_outbox, public.deadline_events from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create function public.cka_in_working_hours(p_ts timestamptz) returns boolean
language plpgsql immutable as $$
declare l timestamp := p_ts at time zone 'Africa/Cairo';
begin
  return public.cka_is_work_day(l::date) and l::time >= time '08:00' and l::time < time '18:00';
end $$;

create function public.cka_enqueue_email(p_user uuid, p_template text, p_payload jsonb, p_dedupe text default null) returns void
language plpgsql security definer set search_path = public as $$
declare e text; lang text;
begin
  select u.email, p.language into e, lang
    from auth.users u join public.profiles p on p.id = u.id
   where u.id = p_user and p.active;
  if e is null then return; end if;
  insert into public.email_outbox (user_id, to_email, language, template, payload, dedupe_key)
  values (p_user, e, lang, p_template, coalesce(p_payload, '{}'), p_dedupe)
  on conflict (dedupe_key) do nothing;
end $$;

-- Who is told about a case: the person it is assigned to, otherwise the people for its level.
create function public.cka_alert_recipients(p_assigned uuid, p_level int, p_child uuid) returns setof uuid
language plpgsql stable security definer set search_path = public as $$
begin
  if p_assigned is not null and exists (select 1 from public.profiles where id = p_assigned and active) then
    return next p_assigned; return;
  end if;
  if p_level = 2 then
    return query select cl.head_teacher_id from public.children c join public.classes cl on cl.id = c.class_id
                  join public.profiles h on h.id = cl.head_teacher_id and h.active where c.id = p_child;
    if found then return; end if;
  end if;
  if p_level >= 4 then
    return query select id from public.profiles where role = 'owner' and active;
  elsif p_level = 3 then
    return query select id from public.profiles where role = 'manager' and active;
  else
    return query select id from public.profiles where role = 'admin' and active;
  end if;
  if not found then
    return query select id from public.profiles where role in ('manager', 'owner') and active;
  end if;
end $$;

create function public.cka_case_payload(s public.submissions) returns jsonb
language sql stable as $$
  select jsonb_build_object('id', s.id, 'ref_no', s.ref_no, 'title', s.title, 'urgency', s.urgency,
                            'level', s.escalation_level, 'acknowledge_by', s.acknowledge_by, 'resolve_by', s.resolve_by)
$$;

-- ---------------------------------------------------------------------------
-- Emails triggered by what happens to a case
-- ---------------------------------------------------------------------------
create function public.cka_notify_submission_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare u uuid;
begin
  perform public.cka_enqueue_email(new.parent_id, 'received', public.cka_case_payload(new), 'received:' || new.id);
  if new.assigned_to is not null then
    perform public.cka_enqueue_email(new.assigned_to, 'assigned', public.cka_case_payload(new), 'assigned:' || new.id || ':' || new.assigned_to);
  end if;
  if new.urgency = 'critical' then
    for u in select id from public.profiles where role in ('manager', 'owner') and active loop
      perform public.cka_enqueue_email(u, 'critical_alert', public.cka_case_payload(new), 'critical:' || new.id || ':' || u);
    end loop;
  end if;
  return new;
end $$;
create trigger submissions_after_insert_notify after insert on public.submissions
  for each row execute function public.cka_notify_submission_insert();

create function public.cka_notify_submission_update() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  reason text := nullif(btrim(coalesce(current_setting('app.change_reason', true), '')), '');
  u uuid;
begin
  if new.status is distinct from old.status then
    if new.status = 'acknowledged' then
      perform public.cka_enqueue_email(new.parent_id, 'acknowledged', public.cka_case_payload(new), 'ack:' || new.id);
    elsif new.status = 'resolved' then
      perform public.cka_enqueue_email(new.parent_id, 'resolved', public.cka_case_payload(new), 'resolved:' || new.id || ':' || extract(epoch from now())::bigint);
    end if;
  end if;
  if new.urgency is distinct from old.urgency then
    perform public.cka_enqueue_email(new.parent_id, 'urgency_changed',
      public.cka_case_payload(new) || jsonb_build_object('old_urgency', old.urgency, 'reason', reason),
      'urgency:' || new.id || ':' || extract(epoch from now())::bigint);
    if new.urgency = 'critical' then
      for u in select id from public.profiles where role in ('manager', 'owner') and active loop
        perform public.cka_enqueue_email(u, 'critical_alert', public.cka_case_payload(new), 'critical:' || new.id || ':' || u);
      end loop;
    end if;
  end if;
  if new.assigned_to is distinct from old.assigned_to and new.assigned_to is not null
     and new.assigned_to is distinct from auth.uid()
     and coalesce(current_setting('app.suppress_assign_email', true), '') <> '1' then
    perform public.cka_enqueue_email(new.assigned_to, 'assigned', public.cka_case_payload(new),
      'assigned:' || new.id || ':' || new.assigned_to || ':' || extract(epoch from now())::bigint);
  end if;
  return new;
end $$;
create trigger submissions_after_update_notify after update on public.submissions
  for each row execute function public.cka_notify_submission_update();

-- A staff update on a case: tell the parent there is news (not what it says).
create function public.cka_notify_event_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare s public.submissions;
begin
  if new.event_type = 'update' and new.visible_to_parent then
    select * into s from public.submissions where id = new.submission_id;
    perform public.cka_enqueue_email(s.parent_id, 'update_added', public.cka_case_payload(s), 'update:' || new.id);
  end if;
  return new;
end $$;
create trigger submission_events_after_insert_notify after insert on public.submission_events
  for each row execute function public.cka_notify_event_insert();

-- Investigation steps: tell the parent(s) a step was completed (the automatic "opened" step is skipped).
create function public.cka_notify_step_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare inv public.investigations; sub public.submissions; child uuid; p uuid; payload jsonb;
begin
  if new.step = 'opened' then return new; end if;
  select * into inv from public.investigations where id = new.investigation_id;
  if inv.submission_id is not null then
    select * into sub from public.submissions where id = inv.submission_id;
    perform public.cka_enqueue_email(sub.parent_id, 'investigation_step',
      public.cka_case_payload(sub) || jsonb_build_object('step', new.step), 'step:' || new.id || ':' || sub.parent_id);
  else
    select child_id into child from public.incidents where id = inv.incident_id;
    for p in select parent_id from public.parent_children where child_id = child loop
      perform public.cka_enqueue_email(p, 'investigation_step', jsonb_build_object('step', new.step, 'accident', true), 'step:' || new.id || ':' || p);
    end loop;
  end if;
  return new;
end $$;
create trigger investigation_steps_after_insert_notify after insert on public.investigation_steps
  for each row execute function public.cka_notify_step_insert();

-- An accident: both parents are told there is a report (no details in the email); a serious one also alerts management.
create function public.cka_notify_incident_insert() returns trigger
language plpgsql security definer set search_path = public as $$
declare p uuid;
begin
  for p in select parent_id from public.parent_children where child_id = new.child_id loop
    perform public.cka_enqueue_email(p, 'accident_report', jsonb_build_object('incident_id', new.id), 'accident:' || new.id || ':' || p);
  end loop;
  if new.severity = 'serious' then
    for p in select id from public.profiles where role in ('manager', 'owner') and active loop
      perform public.cka_enqueue_email(p, 'serious_accident', jsonb_build_object('incident_id', new.id), 'serious:' || new.id || ':' || p);
    end loop;
  end if;
  return new;
end $$;
create trigger incidents_after_insert_notify after insert on public.incidents
  for each row execute function public.cka_notify_incident_insert();

-- ---------------------------------------------------------------------------
-- The deadline clock. Run every 15 minutes by the scheduler (see supabase/schedule-emails.sql).
-- ---------------------------------------------------------------------------
create function public.cka_run_deadline_check(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.submissions;
  d record; r uuid; ins int;
  warned int := 0; escalated int := 0; top int := 0; requeued int := 0;
  in_hours boolean := public.cka_in_working_hours(p_now);
  newlvl int; who uuid; next_at timestamptz;
begin
  -- Staff are told by the "escalated" email below, not also by the generic "assigned" one.
  perform set_config('app.suppress_assign_email', '1', true);

  for s in select * from public.submissions where status in ('received', 'acknowledged', 'in_progress') order by created_at loop
    for d in select * from (values
               ('ack', case when s.acknowledged_at is null then s.acknowledge_by end),
               ('resolve', s.resolve_by)) as t(kind, deadline) loop
      continue when d.deadline is null;
      continue when not in_hours and s.urgency <> 'critical';        -- deadlines pause outside working hours

      -- 1 hour before: warn whoever is handling it (once per deadline)
      if p_now < d.deadline and p_now >= d.deadline - interval '1 hour' and not (s.urgency = 'critical' and d.kind = 'ack') then
        insert into public.deadline_events (submission_id, kind, deadline, action, level)
        values (s.id, d.kind, d.deadline, 'warned', 0) on conflict do nothing;
        get diagnostics ins = row_count;
        if ins = 1 then
          for r in select * from public.cka_alert_recipients(s.assigned_to, s.escalation_level, s.child_id) loop
            perform public.cka_enqueue_email(r, 'deadline_warning', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline),
              'warn:' || s.id || ':' || d.kind || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
          end loop;
          warned := warned + 1;
        end if;
      end if;

      -- missed: move up one level (at most once per escalation window)
      if p_now >= d.deadline and (s.next_escalation_at is null or p_now >= s.next_escalation_at) then
        if s.escalation_level < 4 then
          newlvl := s.escalation_level + 1;
          who := public.cka_level_assignee(newlvl, s.child_id, s.about_staff_member);
          next_at := case when s.urgency = 'critical' then p_now + interval '1 hour'
                          else public.cka_add_working_hours(p_now at time zone 'Africa/Cairo', 2) at time zone 'Africa/Cairo' end;
          perform set_config('app.change_reason', 'escalated automatically: deadline missed', true);
          update public.submissions
             set escalation_level = newlvl, assigned_to = coalesce(who, assigned_to), next_escalation_at = next_at
           where id = s.id;
          insert into public.deadline_events (submission_id, kind, deadline, action, level)
          values (s.id, d.kind, d.deadline, 'escalated', newlvl) on conflict do nothing;
          for r in select * from public.cka_alert_recipients(who, newlvl, s.child_id) loop
            perform public.cka_enqueue_email(r, 'escalated', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline, 'level', newlvl),
              'esc:' || s.id || ':' || newlvl || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
          end loop;
          escalated := escalated + 1;
        else
          -- already with the owner: tell the owner once that it is overdue
          insert into public.deadline_events (submission_id, kind, deadline, action, level)
          values (s.id, d.kind, d.deadline, 'top', 4) on conflict do nothing;
          get diagnostics ins = row_count;
          if ins = 1 then
            for r in select id from public.profiles where role = 'owner' and active loop
              perform public.cka_enqueue_email(r, 'overdue_top', public.cka_case_payload(s) || jsonb_build_object('kind', d.kind, 'deadline', d.deadline),
                'top:' || s.id || ':' || d.kind || ':' || extract(epoch from d.deadline)::bigint || ':' || r);
            end loop;
            top := top + 1;
          end if;
        end if;
        exit;     -- one escalation per case per run
      end if;
    end loop;
  end loop;

  -- Emails stuck "sending" for 10 minutes (the sender crashed) go back in the queue.
  update public.email_outbox set status = 'pending' where status = 'sending' and claimed_at < p_now - interval '10 minutes';
  get diagnostics requeued = row_count;

  return jsonb_build_object('warned', warned, 'escalated', escalated, 'overdue_at_top', top, 'requeued', requeued, 'in_working_hours', in_hours);
end $$;

-- Only the server (service key) may run the checker or touch the queue helpers.
revoke all on function
  public.cka_in_working_hours(timestamptz), public.cka_enqueue_email(uuid, text, jsonb, text),
  public.cka_alert_recipients(uuid, int, uuid), public.cka_case_payload(public.submissions),
  public.cka_run_deadline_check(timestamptz)
from public;
grant execute on function public.cka_run_deadline_check(timestamptz) to service_role;

-- ============================================================
-- migrations/20261006121000_reports.sql
-- ============================================================
-- Manager and owner reports (Prompt 9). One function returns every number for a period, so the
-- page, the CSV download and the tests all use the same source. Manager and owner only.
--
-- Definitions (all dates are Cairo time, the period runs from the start of p_from to the end of p_to):
--   * Cases are counted by the day they were received.
--   * "Acknowledged on time" = acknowledged by the promised time, out of the cases whose acknowledge
--     deadline has passed or that were acknowledged. "Resolved on time" works the same way.
--   * "Overdue now" and "investigations still open" are about right now, not the period.
--   * Average time to resolve is wall-clock hours from received to resolved.
--   * Escalations come from the case timeline (each time a case moved up a level in the period).
--   * Ratings: this is the month containing the end of the period, compared with the month before.

create function public.staff_report(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  f timestamptz; t timestamptz; m0 date; m1 date; out jsonb;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  if p_from is null or p_to is null or p_to < p_from then raise exception 'Choose a valid period'; end if;
  if p_to - p_from > 800 then raise exception 'The period is too long'; end if;

  f := p_from::timestamp at time zone 'Africa/Cairo';
  t := (p_to + 1)::timestamp at time zone 'Africa/Cairo';
  m0 := date_trunc('month', p_to)::date;
  m1 := (m0 - interval '1 month')::date;

  with
  subs as (select * from public.submissions where created_at >= f and created_at < t),
  ack as (select * from subs where acknowledged_at is not null or acknowledge_by <= now()),
  res as (select * from subs where resolved_at is not null or resolve_by <= now()),
  esc as (select e.* from public.submission_events e where e.event_type = 'escalated' and e.created_at >= f and e.created_at < t),
  inc as (select i.*, coalesce(cl.name, '—') as class_name from public.incidents i
            join public.children c on c.id = i.child_id left join public.classes cl on cl.id = c.class_id
           where i.occurred_at >= f and i.occurred_at < t),
  rat as (select r.*, coalesce(cl.name, '—') as class_name from public.ratings r left join public.classes cl on cl.id = r.class_id)
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'totals', jsonb_build_object(
        'received', (select count(*) from subs),
        'open_now', (select count(*) from public.submissions where status in ('received', 'acknowledged', 'in_progress')),
        'overdue_now', (select count(*) from public.submissions s
                         where (s.status = 'received' and s.acknowledge_by < now())
                            or (s.status in ('acknowledged', 'in_progress') and s.resolve_by < now()))),
    'by_type_urgency', coalesce((select jsonb_agg(jsonb_build_object('type', type, 'urgency', urgency, 'count', n) order by type, urgency)
                                   from (select type, urgency, count(*) n from subs group by 1, 2) x), '[]'),
    'on_time', jsonb_build_object(
        'acknowledged', jsonb_build_object(
            'due', (select count(*) from ack),
            'on_time', (select count(*) from ack where acknowledged_at is not null and acknowledged_at <= acknowledge_by)),
        'resolved', jsonb_build_object(
            'due', (select count(*) from res),
            'on_time', (select count(*) from res where resolved_at is not null and resolved_at <= resolve_by))),
    'avg_resolve_hours', (select round((avg(extract(epoch from (resolved_at - created_at))) / 3600)::numeric, 1) from subs where resolved_at is not null),
    'escalations', jsonb_build_object(
        'cases', (select count(distinct submission_id) from esc),
        'moves', (select count(*) from esc),
        'by_level', coalesce((select jsonb_agg(jsonb_build_object('level', lvl, 'count', n) order by lvl)
                                from (select new_value::int as lvl, count(*) n from esc group by 1) x), '[]')),
    'satisfaction', jsonb_build_object(
        'yes', (select count(*) from subs where parent_satisfied is true),
        'no', (select count(*) from subs where parent_satisfied is false),
        'waiting', (select count(*) from subs where status = 'resolved' and parent_satisfied is null)),
    'incidents', jsonb_build_object(
        'total', (select count(*) from inc),
        'by_class', coalesce((select jsonb_agg(jsonb_build_object('name', class_name, 'count', n) order by n desc, class_name)
                                from (select class_name, count(*) n from inc group by 1) x), '[]'),
        'by_location', coalesce((select jsonb_agg(jsonb_build_object('name', loc, 'count', n) order by n desc, loc)
                                   from (select min(btrim(location)) as loc, count(*) n from inc group by lower(btrim(location))) x), '[]'),
        'by_severity', coalesce((select jsonb_agg(jsonb_build_object('name', severity, 'count', n) order by severity)
                                   from (select severity, count(*) n from inc group by 1) x), '[]'),
        'open_investigations', (select count(*) from public.investigations where status = 'open')),
    'ratings', jsonb_build_object(
        'month', m0, 'previous_month', m1,
        'classes', coalesce((select jsonb_agg(jsonb_build_object(
              'name', c.class_name,
              'count', c.n, 'care', c.care, 'communication', c.comm, 'daily', c.daily,
              'prev_count', coalesce(p.n, 0), 'prev_care', p.care, 'prev_communication', p.comm, 'prev_daily', p.daily) order by c.class_name)
            from (select class_name, count(*) n, round(avg(care_score), 2) care, round(avg(communication_score), 2) comm, round(avg(daily_reports_score), 2) daily
                    from rat where month = m0 group by 1) c
            left join (select class_name, count(*) n, round(avg(care_score), 2) care, round(avg(communication_score), 2) comm, round(avg(daily_reports_score), 2) daily
                         from rat where month = m1 group by 1) p on p.class_name = c.class_name), '[]'),
        'compliments', coalesce((select jsonb_agg(jsonb_build_object('staff', staff, 'count', n, 'items', items) order by n desc, staff)
            from (select coalesce(st.full_name, '—') as staff, count(*) n,
                         jsonb_agg(jsonb_build_object('month', r.month, 'text', r.compliment_text) order by r.created_at) as items
                    from public.ratings r left join public.profiles st on st.id = r.compliment_staff_id
                   where r.created_at >= f and r.created_at < t and (r.compliment_staff_id is not null or nullif(btrim(r.compliment_text), '') is not null)
                   group by 1) x), '[]'))
  ) into out;

  return out;
end $$;

revoke all on function public.staff_report(date, date) from public;
grant execute on function public.staff_report(date, date) to authenticated;

-- ============================================================
-- migrations/20261006121100_owner_dashboard.sql
-- ============================================================
-- The owner's private dashboard (Prompt 9b): staff attendance, HR log, staff concerns,
-- repeated mistakes, confirmed investigation faults, editable thresholds, and one function that
-- returns every dashboard number for a period.
--
-- PRIVACY: every table here is readable ONLY by an active user whose role is 'owner' (enforced by
-- row-level security, not by hiding a menu). Not the manager, not admin, not teachers, not parents.
--   * Admin/manager can RECORD attendance, but cannot read it back (record_staff_attendance()).
--   * Any staff member can raise a concern; if they choose "anonymous", NO name is stored anywhere
--     (raised_by stays empty, the time is rounded to the day, and a constraint forbids a name).
--   * Only CONFIRMED faults count against a staff member. An open investigation never does.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.staff_attendance (
  id           uuid primary key default gen_random_uuid(),
  staff_id     uuid not null references public.profiles (id),
  att_date     date not null,
  status       text not null check (status in ('present', 'absent', 'leave')),
  minutes_late int  not null default 0 check (minutes_late between 0 and 600),
  reason       text,
  recorded_by  uuid references public.profiles (id),
  created_at   timestamptz not null default now(),
  unique (staff_id, att_date)
);

create table public.hr_log (
  id              uuid primary key default gen_random_uuid(),
  staff_id        uuid not null references public.profiles (id),
  entry_type      text not null check (entry_type in ('verbal_reminder', 'written_warning', 'final_warning', 'leave', 'contract', 'appraisal', 'praise')),
  entry_date      date not null default current_date,
  note            text,
  follow_up_date  date,
  needs_decision  boolean not null default false,     -- waiting for the owner to decide
  decided_by      uuid references public.profiles (id),
  decided_at      timestamptz,
  created_by      uuid references public.profiles (id),
  created_at      timestamptz not null default now()
);
create index hr_log_staff_idx on public.hr_log (staff_id, entry_date desc);

create table public.staff_complaints (
  id          uuid primary key default gen_random_uuid(),
  raised_by   uuid references public.profiles (id),
  category    text not null check (category in ('supplies', 'workload', 'conduct', 'facilities', 'pay', 'other')),
  description text not null check (length(btrim(description)) > 0),
  status      text not null default 'open' check (status in ('open', 'in_review', 'resolved')),
  anonymous   boolean not null default false,
  created_at  timestamptz not null default now(),
  constraint anonymous_has_no_name check (not anonymous or raised_by is null)
);

-- The fixed (but editable) list of mistake types. "Critical" ones are highlighted on the dashboard.
create table public.mistake_categories (
  id         uuid primary key default gen_random_uuid(),
  name       text not null unique,
  critical   boolean not null default false,
  active     boolean not null default true,
  created_at timestamptz not null default now()
);
insert into public.mistake_categories (name, critical) values
  ('Report without a personal note', false),
  ('Cleaning log not signed', false),
  ('Phone in class', false),
  ('Allergy check missed', true);

create table public.mistakes (
  id            uuid primary key default gen_random_uuid(),
  staff_id      uuid references public.profiles (id),      -- optional
  category_id   uuid not null references public.mistake_categories (id),
  mistake_date  date not null default current_date,
  source        text not null check (source in ('spot_check', 'investigation', 'complaint')),
  confirmed     boolean not null default false,
  note          text,
  created_by    uuid references public.profiles (id),
  created_at    timestamptz not null default now()
);
create index mistakes_staff_idx on public.mistakes (staff_id, mistake_date);

-- A person is linked to an investigation ONLY when its findings confirm responsibility.
create table public.investigation_faults (
  investigation_id uuid primary key references public.investigations (id),
  staff_id         uuid not null references public.profiles (id),
  confirmed        boolean not null default false,
  decided_by       uuid references public.profiles (id),
  decided_at       timestamptz not null default now()
);

create table public.owner_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
-- Thresholds for the Good / Watch / Action needed status, per 30 days (scaled to the period shown).
insert into public.owner_settings (key, value) values ('thresholds', jsonb_build_object(
  'absence_days',     jsonb_build_object('watch', 3,  'action', 6),
  'late_minutes',     jsonb_build_object('watch', 60, 'action', 180),
  'confirmed_faults', jsonb_build_object('watch', 1,  'action', 3),
  'complaints',       jsonb_build_object('watch', 2,  'action', 4)));

-- ---------------------------------------------------------------------------
-- Row-level security: owner only, everywhere
-- ---------------------------------------------------------------------------
alter table public.staff_attendance    enable row level security;
alter table public.hr_log              enable row level security;
alter table public.staff_complaints    enable row level security;
alter table public.mistake_categories  enable row level security;
alter table public.mistakes            enable row level security;
alter table public.investigation_faults enable row level security;
alter table public.owner_settings      enable row level security;

revoke all on public.staff_attendance, public.hr_log, public.staff_complaints, public.mistake_categories,
              public.mistakes, public.investigation_faults, public.owner_settings from anon, authenticated;
grant select on public.staff_attendance, public.hr_log, public.staff_complaints, public.mistake_categories,
                public.mistakes, public.investigation_faults, public.owner_settings to authenticated;
grant insert, update on public.hr_log, public.mistakes, public.mistake_categories, public.owner_settings to authenticated;
grant update (status) on public.staff_complaints to authenticated;

create function public.is_owner() returns boolean
language sql stable security definer set search_path = public as $$ select coalesce(public.auth_role() = 'owner', false) $$;
revoke all on function public.is_owner() from public;
grant execute on function public.is_owner() to authenticated;

create policy owner_attendance_select on public.staff_attendance for select using (public.is_owner());
create policy owner_hr_select  on public.hr_log for select using (public.is_owner());
create policy owner_hr_insert  on public.hr_log for insert with check (public.is_owner());
create policy owner_hr_update  on public.hr_log for update using (public.is_owner()) with check (public.is_owner());
create policy owner_sc_select  on public.staff_complaints for select using (public.is_owner());
create policy owner_sc_update  on public.staff_complaints for update using (public.is_owner()) with check (public.is_owner());
create policy owner_mc_select  on public.mistake_categories for select using (public.is_owner());
create policy owner_mc_insert  on public.mistake_categories for insert with check (public.is_owner());
create policy owner_mc_update  on public.mistake_categories for update using (public.is_owner()) with check (public.is_owner());
create policy owner_m_select   on public.mistakes for select using (public.is_owner());
create policy owner_m_insert   on public.mistakes for insert with check (public.is_owner());
create policy owner_m_update   on public.mistakes for update using (public.is_owner()) with check (public.is_owner());
create policy owner_if_select  on public.investigation_faults for select using (public.is_owner());
create policy owner_os_select  on public.owner_settings for select using (public.is_owner());
create policy owner_os_insert  on public.owner_settings for insert with check (public.is_owner());
create policy owner_os_update  on public.owner_settings for update using (public.is_owner()) with check (public.is_owner());

-- Who wrote an HR entry or mistake is recorded by the database, not claimed by the browser.
create function public.cka_stamp_creator() returns trigger
language plpgsql as $$
begin new.created_by := auth.uid(); return new; end $$;
create trigger hr_log_stamp before insert on public.hr_log for each row execute function public.cka_stamp_creator();
create trigger mistakes_stamp before insert on public.mistakes for each row execute function public.cka_stamp_creator();

-- Deciding an HR item records who and when (the owner).
create function public.cka_hr_decide() returns trigger
language plpgsql as $$
begin
  if old.decided_at is null and new.decided_at is not null then new.decided_by := auth.uid(); end if;
  if new.staff_id is distinct from old.staff_id or new.entry_type is distinct from old.entry_type or new.entry_date is distinct from old.entry_date then
    raise exception 'An HR entry cannot be re-assigned; add a new entry instead';
  end if;
  return new;
end $$;
create trigger hr_log_decide before update on public.hr_log for each row execute function public.cka_hr_decide();

-- ---------------------------------------------------------------------------
-- Recording things (callable by people who cannot read the tables)
-- ---------------------------------------------------------------------------
-- Admin, manager or owner records one person's attendance for a day (replaces an earlier entry).
create function public.record_staff_attendance(p_staff uuid, p_date date, p_status text, p_minutes_late int default 0, p_reason text default null)
returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if p_status not in ('present', 'absent', 'leave') then raise exception 'Invalid status'; end if;
  if p_date is null or p_date > (now() at time zone 'Africa/Cairo')::date then raise exception 'The date cannot be in the future'; end if;
  if p_date < (now() at time zone 'Africa/Cairo')::date - 60 then raise exception 'That date is too far in the past'; end if;
  if not exists (select 1 from public.profiles where id = p_staff and role in ('teacher', 'admin', 'manager', 'owner') and active) then
    raise exception 'Choose an active staff member';
  end if;
  insert into public.staff_attendance (staff_id, att_date, status, minutes_late, reason, recorded_by)
  values (p_staff, p_date, p_status, case when p_status = 'present' then coalesce(p_minutes_late, 0) else 0 end, nullif(btrim(coalesce(p_reason, '')), ''), auth.uid())
  on conflict (staff_id, att_date) do update
    set status = excluded.status, minutes_late = excluded.minutes_late, reason = excluded.reason, recorded_by = excluded.recorded_by;
end $$;

-- The attendance sheet for one day: the staff list for everyone allowed to record, and the saved
-- values only for the owner.
create function public.staff_attendance_day(p_date date)
returns table (staff_id uuid, full_name text, role text, status text, minutes_late int, reason text)
language sql stable security definer set search_path = public as $$
  select p.id, p.full_name, p.role,
         case when public.is_owner() then a.status end,
         case when public.is_owner() then a.minutes_late end,
         case when public.is_owner() then a.reason end
  from public.profiles p
  left join public.staff_attendance a on a.staff_id = p.id and a.att_date = p_date
  where public.is_management() and p.active and p.role in ('teacher', 'admin', 'manager')
  order by p.full_name
$$;

-- Any staff member raises a concern. Anonymous means NOTHING identifying is stored.
create function public.submit_staff_complaint(p_category text, p_description text, p_anonymous boolean default false)
returns void language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() not in ('teacher', 'admin', 'manager', 'owner') then raise exception 'Not allowed'; end if;
  if nullif(btrim(coalesce(p_description, '')), '') is null then raise exception 'Please describe the concern'; end if;
  if coalesce(p_anonymous, false) then
    insert into public.staff_complaints (raised_by, category, description, anonymous, created_at)
    values (null, p_category, btrim(p_description), true, date_trunc('day', now() at time zone 'Africa/Cairo') at time zone 'Africa/Cairo');
  else
    insert into public.staff_complaints (raised_by, category, description, anonymous) values (auth.uid(), p_category, btrim(p_description), false);
  end if;
end $$;

-- Manager or owner: say that an investigation's findings confirm (or do not confirm) a person's responsibility.
create function public.confirm_investigation_fault(p_investigation uuid, p_staff uuid, p_confirmed boolean)
returns void language plpgsql security definer set search_path = public as $$
declare inv public.investigations;
begin
  if not public.is_manager_or_owner() then raise exception 'Not allowed'; end if;
  select * into inv from public.investigations where id = p_investigation;
  if inv.id is null then raise exception 'Not found'; end if;
  if not exists (select 1 from public.investigation_steps where investigation_id = p_investigation and step = 'findings') then
    raise exception 'Responsibility can only be confirmed once the findings have been written';
  end if;
  if inv.status = 'closed' and not public.is_owner() then raise exception 'This investigation is closed'; end if;
  if not exists (select 1 from public.profiles where id = p_staff and role in ('teacher', 'admin', 'manager') and active) then
    raise exception 'Choose an active staff member';
  end if;
  insert into public.investigation_faults (investigation_id, staff_id, confirmed, decided_by, decided_at)
  values (p_investigation, p_staff, coalesce(p_confirmed, false), auth.uid(), now())
  on conflict (investigation_id) do update
    set staff_id = excluded.staff_id, confirmed = excluded.confirmed, decided_by = excluded.decided_by, decided_at = excluded.decided_at;
end $$;

-- What an investigation currently says about responsibility (manager/owner).
create function public.investigation_fault(p_investigation uuid)
returns table (staff_id uuid, staff_name text, confirmed boolean)
language sql stable security definer set search_path = public as $$
  select f.staff_id, p.full_name, f.confirmed
  from public.investigation_faults f join public.profiles p on p.id = f.staff_id
  where f.investigation_id = p_investigation and public.is_manager_or_owner()
$$;

-- ---------------------------------------------------------------------------
-- Dashboard numbers
-- ---------------------------------------------------------------------------
-- A "happy comment": a compliment, or a comment left with high scores (average 4 or more).
create function public.cka_is_happy(r public.ratings) returns boolean
language sql immutable as $$
  select r.compliment_staff_id is not null
      or nullif(btrim(coalesce(r.compliment_text, '')), '') is not null
      or (nullif(btrim(coalesce(r.comment, '')), '') is not null
          and (r.care_score + r.communication_score + r.daily_reports_score) >= 12)
$$;

-- Thresholds are written per 30 days; for a longer or shorter period they are scaled (never below 1).
create function public.cka_threshold(p_th jsonb, p_metric text, p_level text, p_days int) returns int
language sql immutable as $$
  select greatest(1, ceil(coalesce((p_th -> p_metric ->> p_level)::numeric,
    case p_metric || '.' || p_level
      when 'absence_days.watch' then 3 when 'absence_days.action' then 6
      when 'late_minutes.watch' then 60 when 'late_minutes.action' then 180
      when 'confirmed_faults.watch' then 1 when 'confirmed_faults.action' then 3
      when 'complaints.watch' then 2 else 4 end) * p_days / 30.0))::int
$$;

create function public.owner_dashboard(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  n int; pf date; pt date;
  f timestamptz; t timestamptz; pfts timestamptz;
  th jsonb; wk0 date; out jsonb;
begin
  if not public.is_owner() then raise exception 'Not allowed'; end if;
  if p_from is null or p_to is null or p_to < p_from then raise exception 'Choose a valid period'; end if;
  if p_to - p_from > 800 then raise exception 'The period is too long'; end if;

  n := p_to - p_from + 1;
  pf := p_from - n; pt := p_from - 1;                                  -- the period just before, same length
  f := p_from::timestamp at time zone 'Africa/Cairo';
  t := (p_to + 1)::timestamp at time zone 'Africa/Cairo';
  pfts := pf::timestamp at time zone 'Africa/Cairo';
  th := coalesce((select value from public.owner_settings where key = 'thresholds'), '{}'::jsonb);
  wk0 := p_to - extract(dow from p_to)::int;                           -- Sunday of the week containing p_to

  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to, 'days', n, 'previous_from', pf, 'previous_to', pt),
    'thresholds', jsonb_build_object(
        'absence_days', jsonb_build_object('watch', public.cka_threshold(th, 'absence_days', 'watch', 30), 'action', public.cka_threshold(th, 'absence_days', 'action', 30)),
        'late_minutes', jsonb_build_object('watch', public.cka_threshold(th, 'late_minutes', 'watch', 30), 'action', public.cka_threshold(th, 'late_minutes', 'action', 30)),
        'confirmed_faults', jsonb_build_object('watch', public.cka_threshold(th, 'confirmed_faults', 'watch', 30), 'action', public.cka_threshold(th, 'confirmed_faults', 'action', 30)),
        'complaints', jsonb_build_object('watch', public.cka_threshold(th, 'complaints', 'watch', 30), 'action', public.cka_threshold(th, 'complaints', 'action', 30))),

    -- 1. the six tiles, each with the previous period beside it
    'tiles', jsonb_build_object(
      'accidents', jsonb_build_object(
         'value', (select count(*) from public.incidents where occurred_at >= f and occurred_at < t),
         'previous', (select count(*) from public.incidents where occurred_at >= pfts and occurred_at < f)),
      'complaints', jsonb_build_object(
         'value', (select count(*) from public.submissions where type = 'complaint' and created_at >= f and created_at < t),
         'previous', (select count(*) from public.submissions where type = 'complaint' and created_at >= pfts and created_at < f)),
      'happy_comments', jsonb_build_object(
         'value', (select count(*) from public.ratings r where public.cka_is_happy(r) and r.created_at >= f and r.created_at < t),
         'previous', (select count(*) from public.ratings r where public.cka_is_happy(r) and r.created_at >= pfts and r.created_at < f)),
      'absence_days', jsonb_build_object(
         'value', (select count(*) from public.staff_attendance where status = 'absent' and att_date between p_from and p_to),
         'previous', (select count(*) from public.staff_attendance where status = 'absent' and att_date between pf and pt)),
      'late_minutes', jsonb_build_object(
         'value', (select coalesce(sum(minutes_late), 0) from public.staff_attendance where att_date between p_from and p_to),
         'previous', (select coalesce(sum(minutes_late), 0) from public.staff_attendance where att_date between pf and pt)),
      'open_hr', jsonb_build_object(
         'value', (select count(*) from public.hr_log where needs_decision and decided_at is null),
         'opened', (select count(*) from public.hr_log where needs_decision and created_at >= f and created_at < t),
         'previous_opened', (select count(*) from public.hr_log where needs_decision and created_at >= pfts and created_at < f))),

    -- 2 and 3. last 8 weeks (Sunday to Saturday) ending with the week that contains the end of the period
    'weekly', coalesce((select jsonb_agg(jsonb_build_object(
          'week_start', w,
          'accidents', (select count(*) from public.incidents i where (i.occurred_at at time zone 'Africa/Cairo')::date between w and w + 6),
          'complaints', (select count(*) from public.submissions s where s.type = 'complaint' and (s.created_at at time zone 'Africa/Cairo')::date between w and w + 6),
          'happy_comments', (select count(*) from public.ratings r where public.cka_is_happy(r) and (r.created_at at time zone 'Africa/Cairo')::date between w and w + 6)
        ) order by w) from (select gs::date as w from generate_series((wk0 - 49)::timestamp, wk0::timestamp, interval '7 days') as gs) as g), '[]'),

    -- 4. latest accident notes
    'latest_accidents', coalesce((select jsonb_agg(x order by (x ->> 'occurred_at') desc) from (
          select jsonb_build_object('id', i.id, 'occurred_at', i.occurred_at, 'child', c.full_name, 'class', cl.name, 'location', i.location,
                 'severity', i.severity, 'note', left(i.what_happened, 200), 'parent_read', i.parent_signed_at is not null,
                 'investigation', (select v.status from public.investigations v where v.incident_id = i.id)) as x
            from public.incidents i join public.children c on c.id = i.child_id left join public.classes cl on cl.id = c.class_id
           where i.occurred_at >= f and i.occurred_at < t order by i.occurred_at desc limit 10) q), '[]'),

    -- 5. repeated mistakes (confirmed only)
    'mistakes', coalesce((select jsonb_agg(jsonb_build_object('category', name, 'critical', critical, 'count', cnt) order by cnt desc, critical desc, name)
          from (select c.name, c.critical, count(*) as cnt from public.mistakes m join public.mistake_categories c on c.id = m.category_id
                 where m.confirmed and m.mistake_date between p_from and p_to group by 1, 2) q), '[]'),

    -- 6. the staff table
    'staff', coalesce((select jsonb_agg(jsonb_build_object(
          'id', s.id, 'name', s.full_name, 'role', s.role, 'absence_days', s.absence_days, 'late_minutes', s.late_minutes,
          'class_accidents', s.class_accidents, 'confirmed_faults', s.confirmed_faults, 'complaints_about', s.complaints_about,
          'status', case
             when s.absence_days >= public.cka_threshold(th, 'absence_days', 'action', n) or s.late_minutes >= public.cka_threshold(th, 'late_minutes', 'action', n)
               or s.confirmed_faults >= public.cka_threshold(th, 'confirmed_faults', 'action', n) or s.complaints_about >= public.cka_threshold(th, 'complaints', 'action', n) then 'action'
             when s.absence_days >= public.cka_threshold(th, 'absence_days', 'watch', n) or s.late_minutes >= public.cka_threshold(th, 'late_minutes', 'watch', n)
               or s.confirmed_faults >= public.cka_threshold(th, 'confirmed_faults', 'watch', n) or s.complaints_about >= public.cka_threshold(th, 'complaints', 'watch', n) then 'watch'
             else 'good' end) order by s.full_name)
        from (select p.id, p.full_name, p.role,
                (select count(*) from public.staff_attendance a where a.staff_id = p.id and a.status = 'absent' and a.att_date between p_from and p_to)::int as absence_days,
                (select coalesce(sum(a.minutes_late), 0) from public.staff_attendance a where a.staff_id = p.id and a.att_date between p_from and p_to)::int as late_minutes,
                (select count(*) from public.incidents i join public.children c on c.id = i.child_id
                  where i.occurred_at >= f and i.occurred_at < t
                    and (c.class_id in (select sc.class_id from public.staff_classes sc where sc.staff_id = p.id)
                         or c.class_id in (select cl.id from public.classes cl where cl.head_teacher_id = p.id)))::int as class_accidents,
                ((select count(*) from public.investigation_faults ff join public.investigations iv on iv.id = ff.investigation_id
                   where ff.staff_id = p.id and ff.confirmed and iv.opened_at >= f and iv.opened_at < t)
                 + (select count(*) from public.mistakes m where m.staff_id = p.id and m.confirmed and m.mistake_date between p_from and p_to))::int as confirmed_faults,
                (select count(*) from public.submissions sb where sb.about_staff_member = p.id and sb.created_at >= f and sb.created_at < t)::int as complaints_about
              from public.profiles p where p.active and p.role in ('teacher', 'admin', 'manager')) s), '[]'),

    -- 7. HR log: items waiting for the owner first, then newest
    'hr_log', coalesce((select jsonb_agg(x) from (
          select jsonb_build_object('id', h.id, 'staff', p.full_name, 'staff_id', h.staff_id, 'type', h.entry_type, 'date', h.entry_date, 'note', h.note,
                 'follow_up_date', h.follow_up_date, 'awaiting', (h.needs_decision and h.decided_at is null), 'decided_at', h.decided_at,
                 'decided_by', d.full_name) as x
            from public.hr_log h join public.profiles p on p.id = h.staff_id left join public.profiles d on d.id = h.decided_by
           order by (h.needs_decision and h.decided_at is null) desc, h.entry_date desc, h.created_at desc limit 100) q), '[]'),

    -- 8. concerns raised by staff
    'staff_concerns', jsonb_build_object(
      'by_category_status', coalesce((select jsonb_agg(jsonb_build_object('category', category, 'status', status, 'count', cnt) order by category, status)
            from (select category, status, count(*) cnt from public.staff_complaints where created_at >= f and created_at < t group by 1, 2) q), '[]'),
      'recent', coalesce((select jsonb_agg(x) from (
            select jsonb_build_object('id', c.id, 'category', c.category, 'status', c.status, 'description', c.description, 'anonymous', c.anonymous,
                   'raised_by', case when c.anonymous then null else p.full_name end, 'date', (c.created_at at time zone 'Africa/Cairo')::date) as x
              from public.staff_complaints c left join public.profiles p on p.id = c.raised_by
             order by (c.status = 'resolved'), c.created_at desc limit 50) q), '[]')),

    -- 9. feedback per family
    'families', coalesce((select jsonb_agg(x) from (
          select jsonb_build_object('parent', p.full_name, 'complaints', f2.complaints, 'happy', f2.happy,
                 'latest_at', f2.latest_at, 'latest_message', f2.latest_message) as x
            from public.profiles p
            join lateral (select
                 (select count(*) from public.submissions s where s.parent_id = p.id and s.type = 'complaint' and s.created_at >= f and s.created_at < t)::int as complaints,
                 (select count(*) from public.ratings r where r.parent_id = p.id and public.cka_is_happy(r) and r.created_at >= f and r.created_at < t)::int as happy,
                 (select u.at_ from (select s.created_at as at_, s.title || ': ' || left(s.description, 160) as msg from public.submissions s where s.parent_id = p.id
                                     union all
                                     select r.created_at, coalesce(nullif(btrim(r.compliment_text), ''), nullif(btrim(r.comment), '')) from public.ratings r where r.parent_id = p.id) u
                   where u.msg is not null order by u.at_ desc limit 1) as latest_at,
                 (select u.msg from (select s.created_at as at_, s.title || ': ' || left(s.description, 160) as msg from public.submissions s where s.parent_id = p.id
                                     union all
                                     select r.created_at, coalesce(nullif(btrim(r.compliment_text), ''), nullif(btrim(r.comment), '')) from public.ratings r where r.parent_id = p.id) u
                   where u.msg is not null order by u.at_ desc limit 1) as latest_message) f2 on true
           where p.role = 'parent' and (f2.complaints > 0 or f2.happy > 0)
           order by f2.complaints + f2.happy desc, p.full_name limit 50) q), '[]')
  ) into out;
  return out;
end $$;

revoke all on function
  public.record_staff_attendance(uuid, date, text, int, text), public.staff_attendance_day(date),
  public.submit_staff_complaint(text, text, boolean), public.confirm_investigation_fault(uuid, uuid, boolean),
  public.investigation_fault(uuid), public.cka_is_happy(public.ratings), public.cka_threshold(jsonb, text, text, int),
  public.owner_dashboard(date, date)
from public;
grant execute on function
  public.record_staff_attendance(uuid, date, text, int, text), public.staff_attendance_day(date),
  public.submit_staff_complaint(text, text, boolean), public.confirm_investigation_fault(uuid, uuid, boolean),
  public.investigation_fault(uuid), public.owner_dashboard(date, date)
to authenticated;

-- ============================================================
-- migrations/20261006121200_owner_routines.sql
-- ============================================================
-- The owner's daily routine (Prompt 21, "Owner"): a morning-walk and afternoon checklist, a task
-- tracker, and reminders (9:00, 16:30, Thursday review, monthly review). Owner-only, like the rest of
-- the owner's private area. Times are Cairo time; reminders only go out on working days (Sun-Thu).
--
-- The checklist items below are PLACEHOLDERS (the plan says 6 morning checks and 4 afternoon checks
-- but does not list them). The owner edits, adds and switches off items on the Checklist screen.

create table public.checklist_items (
  id         uuid primary key default gen_random_uuid(),
  list       text not null check (list in ('morning', 'afternoon')),
  position   int  not null default 0,
  label      text not null check (length(btrim(label)) > 0),
  active     boolean not null default true,
  created_at timestamptz not null default now()
);
insert into public.checklist_items (list, position, label) values
  ('morning', 1, 'Entrance and reception are tidy and safe'),
  ('morning', 2, 'Every classroom is clean and ready'),
  ('morning', 3, 'Staff are present and on time'),
  ('morning', 4, 'Allergy list is visible in the kitchen and classrooms'),
  ('morning', 5, 'Outdoor area checked for hazards'),
  ('morning', 6, 'Children are welcomed warmly at arrival'),
  ('afternoon', 1, 'Daily reports are written and sent'),
  ('afternoon', 2, 'Cleaning log is signed'),
  ('afternoon', 3, 'Children are handed over to authorised people only'),
  ('afternoon', 4, 'Rooms are tidied and secured');

-- One row per item per day: ok = everything fine, not ok = needs attention (with a note).
create table public.checklist_checks (
  id         uuid primary key default gen_random_uuid(),
  item_id    uuid not null references public.checklist_items (id),
  check_date date not null,
  ok         boolean not null,
  note       text,
  checked_at timestamptz not null default now(),
  unique (item_id, check_date)
);

create table public.owner_tasks (
  id          uuid primary key default gen_random_uuid(),
  what        text not null check (length(btrim(what)) > 0),
  assigned_to uuid references public.profiles (id),              -- "who"
  due_date    date not null,
  status      text not null default 'not_started' check (status in ('not_started', 'in_progress', 'done')),
  note        text,
  created_by  uuid references public.profiles (id),
  created_at  timestamptz not null default now(),
  done_at     timestamptz
);
create index owner_tasks_due_idx on public.owner_tasks (due_date) where status <> 'done';

alter table public.checklist_items  enable row level security;
alter table public.checklist_checks enable row level security;
alter table public.owner_tasks      enable row level security;
revoke all on public.checklist_items, public.checklist_checks, public.owner_tasks from anon, authenticated;
grant select on public.checklist_items, public.checklist_checks, public.owner_tasks to authenticated;
grant insert, update on public.checklist_items, public.owner_tasks to authenticated;

create policy owner_ci_select on public.checklist_items  for select using (public.is_owner());
create policy owner_ci_insert on public.checklist_items  for insert with check (public.is_owner());
create policy owner_ci_update on public.checklist_items  for update using (public.is_owner()) with check (public.is_owner());
create policy owner_cc_select on public.checklist_checks for select using (public.is_owner());
create policy owner_ot_select on public.owner_tasks      for select using (public.is_owner());
create policy owner_ot_insert on public.owner_tasks      for insert with check (public.is_owner());
create policy owner_ot_update on public.owner_tasks      for update using (public.is_owner()) with check (public.is_owner());

create trigger owner_tasks_stamp before insert on public.owner_tasks for each row execute function public.cka_stamp_creator();

-- "Done" records when; reopening clears it.
create function public.cka_task_done_at() returns trigger
language plpgsql as $$
begin
  if new.status = 'done' and old.status <> 'done' then new.done_at := now(); end if;
  if new.status <> 'done' then new.done_at := null; end if;
  return new;
end $$;
create trigger owner_tasks_done before update on public.owner_tasks for each row execute function public.cka_task_done_at();

-- ---------------------------------------------------------------------------
-- Tick one check (the owner, for today or up to a week back)
-- ---------------------------------------------------------------------------
create function public.owner_set_check(p_item uuid, p_date date, p_ok boolean, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare today date := (now() at time zone 'Africa/Cairo')::date;
begin
  if not public.is_owner() then raise exception 'Not allowed'; end if;
  if p_date is null or p_date > today or p_date < today - 7 then raise exception 'Choose today or one of the last 7 days'; end if;
  if not exists (select 1 from public.checklist_items where id = p_item and active) then raise exception 'That check is not in use'; end if;
  if p_ok is false and nullif(btrim(coalesce(p_note, '')), '') is null then raise exception 'Please say what needs attention'; end if;
  insert into public.checklist_checks (item_id, check_date, ok, note, checked_at)
  values (p_item, p_date, p_ok, nullif(btrim(coalesce(p_note, '')), ''), now())
  on conflict (item_id, check_date) do update set ok = excluded.ok, note = excluded.note, checked_at = now();
end $$;

-- ---------------------------------------------------------------------------
-- Everything the Checklist screen needs for one day
-- ---------------------------------------------------------------------------
create function public.owner_routine(p_date date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := (now() at time zone 'Africa/Cairo')::date; d date; out jsonb;
begin
  if not public.is_owner() then raise exception 'Not allowed'; end if;
  d := coalesce(p_date, today);
  if d > today or d < today - 7 then raise exception 'Choose today or one of the last 7 days'; end if;

  select jsonb_build_object(
    'date', d, 'today', today, 'is_thursday', extract(dow from today) = 4,
    'lists', (select jsonb_object_agg(l.list, jsonb_build_object(
        'items', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'label', i.label, 'position', i.position, 'ok', c.ok, 'note', c.note, 'checked_at', c.checked_at) order by i.position, i.created_at)
                             from public.checklist_items i left join public.checklist_checks c on c.item_id = i.id and c.check_date = d
                            where i.list = l.list and i.active), '[]'),
        'total', (select count(*) from public.checklist_items i where i.list = l.list and i.active),
        'done', (select count(*) from public.checklist_items i join public.checklist_checks c on c.item_id = i.id and c.check_date = d where i.list = l.list and i.active),
        'attention', (select count(*) from public.checklist_items i join public.checklist_checks c on c.item_id = i.id and c.check_date = d where i.list = l.list and i.active and not c.ok)))
      from (values ('morning'), ('afternoon')) as l(list)),
    'history', (select jsonb_agg(jsonb_build_object('date', h, 'working_day', public.cka_is_work_day(h),
        'morning', (select count(*) from public.checklist_items i join public.checklist_checks c on c.item_id = i.id and c.check_date = h where i.list = 'morning' and i.active),
        'morning_total', (select count(*) from public.checklist_items i where i.list = 'morning' and i.active),
        'afternoon', (select count(*) from public.checklist_items i join public.checklist_checks c on c.item_id = i.id and c.check_date = h where i.list = 'afternoon' and i.active),
        'afternoon_total', (select count(*) from public.checklist_items i where i.list = 'afternoon' and i.active)) order by h desc)
      from generate_series((today - 6)::timestamp, today::timestamp, interval '1 day') as g(h0), lateral (select h0::date as h) x),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'what', t.what, 'assigned_to', t.assigned_to, 'who', p.full_name, 'due_date', t.due_date, 'status', t.status,
          'late', (t.status <> 'done' and t.due_date < today), 'note', t.note, 'done_at', t.done_at)
          order by (t.status = 'done'), t.due_date, t.created_at)
        from public.owner_tasks t left join public.profiles p on p.id = t.assigned_to
       where t.status <> 'done' or t.done_at >= now() - interval '14 days'), '[]'),
    'late_tasks', (select count(*) from public.owner_tasks where status <> 'done' and due_date < today)
  ) into out;
  return out;
end $$;

-- ---------------------------------------------------------------------------
-- Reminders (run by the 15-minute scheduler, together with the deadline clock)
--   09:00  morning walk not finished       16:30  afternoon check not finished
--   Thursday 09:00  weekly review (with the number of late tasks)
--   First working day of the month, 09:00  monthly review
-- Each is sent at most once per day, on working days only, and a late scheduler still catches it
-- within a few hours.
-- ---------------------------------------------------------------------------
create function public.cka_run_owner_reminders(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  l timestamp := p_now at time zone 'Africa/Cairo';
  d date := l::date; tm time := l::time; dow int := extract(dow from l::date)::int;
  o uuid; sent int := 0; late int; fd date; k text; done int; total int; existed boolean;

  -- send once; count only if it really was queued now
begin
  if not public.cka_is_work_day(d) then return jsonb_build_object('sent', 0, 'working_day', false); end if;
  select count(*) into late from public.owner_tasks where status <> 'done' and due_date < d;

  for o in select id from public.profiles where role = 'owner' and active loop
    -- morning walk
    if tm >= time '09:00' and tm < time '12:00' then
      select count(*) filter (where c.id is not null), count(*) into done, total
        from public.checklist_items i left join public.checklist_checks c on c.item_id = i.id and c.check_date = d where i.list = 'morning' and i.active;
      k := 'chk-am:' || d || ':' || o; existed := exists (select 1 from public.email_outbox where dedupe_key = k);
      if total > 0 and done < total then
        perform public.cka_enqueue_email(o, 'checklist_morning', jsonb_build_object('date', d, 'done', done, 'total', total), k);
        if not existed then sent := sent + 1; end if;
      end if;
    end if;
    -- afternoon check
    if tm >= time '16:30' and tm < time '18:00' then
      select count(*) filter (where c.id is not null), count(*) into done, total
        from public.checklist_items i left join public.checklist_checks c on c.item_id = i.id and c.check_date = d where i.list = 'afternoon' and i.active;
      k := 'chk-pm:' || d || ':' || o; existed := exists (select 1 from public.email_outbox where dedupe_key = k);
      if total > 0 and done < total then
        perform public.cka_enqueue_email(o, 'checklist_afternoon', jsonb_build_object('date', d, 'done', done, 'total', total), k);
        if not existed then sent := sent + 1; end if;
      end if;
    end if;
    -- Thursday review
    if dow = 4 and tm >= time '09:00' and tm < time '12:00' then
      k := 'rev-thu:' || d || ':' || o; existed := exists (select 1 from public.email_outbox where dedupe_key = k);
      perform public.cka_enqueue_email(o, 'review_thursday', jsonb_build_object('date', d, 'late_tasks', late), k);
      if not existed then sent := sent + 1; end if;
    end if;
    -- monthly review: the first working day of the month
    fd := date_trunc('month', d)::date;
    while not public.cka_is_work_day(fd) loop fd := fd + 1; end loop;
    if d = fd and tm >= time '09:00' and tm < time '12:00' then
      k := 'rev-mon:' || to_char(d, 'YYYY-MM') || ':' || o; existed := exists (select 1 from public.email_outbox where dedupe_key = k);
      perform public.cka_enqueue_email(o, 'review_monthly', jsonb_build_object('date', d, 'late_tasks', late), k);
      if not existed then sent := sent + 1; end if;
    end if;
  end loop;
  return jsonb_build_object('sent', sent, 'working_day', true, 'late_tasks', late);
end $$;

revoke all on function public.owner_set_check(uuid, date, boolean, text), public.owner_routine(date), public.cka_run_owner_reminders(timestamptz) from public;
grant execute on function public.owner_set_check(uuid, date, boolean, text), public.owner_routine(date) to authenticated;
grant execute on function public.cka_run_owner_reminders(timestamptz) to service_role;

-- ============================================================
-- migrations/20261006121400_registration.sql
-- ============================================================
-- Online child registration (Prompt 11).
--
-- A family fills in the public registration form (no login). The server stores the application with the
-- service key (nobody can write these tables from a browser). Staff review it, and approving it creates
-- the child's record and invites the parents.
--
-- WHO CAN SEE WHAT (enforced here, in the database):
--   applications, health details, ID photos, documents ... admin, manager, owner
--   a child's allergies ................................. also the child's class teachers (ONLY allergies)
--   a child's own details ............................... that child's parents (they can update pickup
--                                                         people and allergies; staff are told)
--   everyone else, including other parents .............. nothing

-- ---------------------------------------------------------------------------
-- Applications (before approval)
-- ---------------------------------------------------------------------------
create table public.registration_applications (
  id               uuid primary key default gen_random_uuid(),
  application_no   bigint generated always as identity unique,
  draft_id         uuid not null,
  status           text not null default 'new' check (status in ('new', 'missing_documents', 'tour_booked', 'approved', 'waitlist', 'declined')),
  status_note      text,
  language         text not null default 'en' check (language in ('ar', 'en')),
  child_name       text not null check (length(btrim(child_name)) between 2 and 120),
  child_dob        date not null,
  programme        text not null check (programme in ('nursery', 'preschool', 'after_school', 'camp')),
  preferred_start  date,
  child_photo_path text,
  allergies        text,
  medical_conditions text,
  medications      text,
  doctor_name      text,
  doctor_phone     text,
  consent_photos_class       boolean not null,
  consent_photos_social      boolean not null,
  consent_outings            boolean not null,
  consent_emergency_treatment boolean not null,
  consent_birthday_wall      boolean not null,
  child_id         uuid references public.children (id),
  assigned_class_id uuid references public.classes (id),
  decided_by       uuid references public.profiles (id),
  decided_at       timestamptz,
  created_at       timestamptz not null default now()
);
create index registration_status_idx on public.registration_applications (status, created_at desc);

create table public.registration_parents (
  id             uuid primary key default gen_random_uuid(),
  application_id uuid not null references public.registration_applications (id),
  position       smallint not null check (position in (1, 2)),
  full_name      text not null,
  phone          text not null,
  email          text not null,
  relationship   text not null check (relationship in ('mother', 'father', 'guardian', 'other')),
  unique (application_id, position)
);

create table public.registration_pickups (
  id              uuid primary key default gen_random_uuid(),
  application_id  uuid not null references public.registration_applications (id),
  full_name       text not null,
  relationship    text not null,
  phone           text not null,
  id_photo_path   text
);

create table public.registration_documents (
  id              uuid primary key default gen_random_uuid(),
  application_id  uuid not null references public.registration_applications (id),
  kind            text not null check (kind in ('birth_certificate', 'vaccination_record', 'other')),
  storage_path    text not null,
  file_name       text,
  mime_type       text not null,
  size_bytes      integer not null check (size_bytes > 0 and size_bytes <= 5242880)
);

create table public.registration_events (
  id              uuid primary key default gen_random_uuid(),
  application_id  uuid not null references public.registration_applications (id),
  actor_id        uuid references public.profiles (id),
  actor_name      text,
  kind            text not null,
  note            text,
  created_at      timestamptz not null default now()
);

-- Simple counters so the public form cannot be hammered (server only).
create table public.registration_rate (
  key     text not null,
  bucket  timestamptz not null,
  n       int not null default 0,
  primary key (key, bucket)
);

-- ---------------------------------------------------------------------------
-- A child's records after approval
-- ---------------------------------------------------------------------------
create table public.child_health (
  child_id           uuid primary key references public.children (id),
  allergies          text,
  medical_conditions text,
  medications        text,
  doctor_name        text,
  doctor_phone       text,
  updated_at         timestamptz not null default now(),
  updated_by         uuid references public.profiles (id)
);

create table public.child_pickups (
  id            uuid primary key default gen_random_uuid(),
  child_id      uuid not null references public.children (id),
  full_name     text not null check (length(btrim(full_name)) > 0),
  relationship  text not null,
  phone         text not null,
  id_photo_path text,
  active        boolean not null default true,
  created_at    timestamptz not null default now()
);
create index child_pickups_child_idx on public.child_pickups (child_id) where active;

create table public.child_consents (
  child_id                    uuid primary key references public.children (id),
  photos_class                boolean not null,
  photos_social               boolean not null,
  outings                     boolean not null,
  emergency_treatment         boolean not null,
  birthday_wall               boolean not null,
  updated_at                  timestamptz not null default now(),
  updated_by                  uuid references public.profiles (id)
);

create table public.child_documents (
  id            uuid primary key default gen_random_uuid(),
  child_id      uuid not null references public.children (id),
  kind          text not null check (kind in ('birth_certificate', 'vaccination_record', 'child_photo', 'other')),
  storage_path  text not null,
  file_name     text,
  mime_type     text,
  size_bytes    integer,
  created_at    timestamptz not null default now()
);

-- Every change to health, consent or the pickup list: who, when, what (management only).
create table public.child_change_log (
  id              uuid primary key default gen_random_uuid(),
  child_id        uuid not null references public.children (id),
  kind            text not null check (kind in ('created', 'health', 'pickup', 'consent', 'contact')),
  summary         text not null,
  old_value       text,
  new_value       text,
  changed_by      uuid references public.profiles (id),
  changed_by_name text,
  created_at      timestamptz not null default now()
);
create index child_change_log_idx on public.child_change_log (child_id, created_at desc);

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------
alter table public.registration_applications enable row level security;
alter table public.registration_parents       enable row level security;
alter table public.registration_pickups       enable row level security;
alter table public.registration_documents     enable row level security;
alter table public.registration_events        enable row level security;
alter table public.registration_rate          enable row level security;
alter table public.child_health               enable row level security;
alter table public.child_pickups              enable row level security;
alter table public.child_consents             enable row level security;
alter table public.child_documents            enable row level security;
alter table public.child_change_log           enable row level security;

revoke all on public.registration_applications, public.registration_parents, public.registration_pickups, public.registration_documents,
              public.registration_events, public.registration_rate, public.child_health, public.child_pickups, public.child_consents,
              public.child_documents, public.child_change_log from anon, authenticated;
-- Everything is written through checked functions below; browsers only ever READ, and only what the policies allow.
grant select on public.registration_applications, public.registration_parents, public.registration_pickups, public.registration_documents,
                public.registration_events, public.child_health, public.child_pickups, public.child_consents, public.child_documents,
                public.child_change_log to authenticated;

create policy reg_app_select  on public.registration_applications for select using (public.is_management());
create policy reg_par_select  on public.registration_parents       for select using (public.is_management());
create policy reg_pick_select on public.registration_pickups       for select using (public.is_management());
create policy reg_doc_select  on public.registration_documents     for select using (public.is_management());
create policy reg_ev_select   on public.registration_events        for select using (public.is_management());

create policy child_health_staff   on public.child_health   for select using (public.is_management());
create policy child_health_parent  on public.child_health   for select using (public.auth_role() = 'parent' and public.can_see_child(child_id));
create policy child_pick_staff     on public.child_pickups  for select using (public.is_management());
create policy child_pick_parent    on public.child_pickups  for select using (public.auth_role() = 'parent' and public.can_see_child(child_id));
create policy child_cons_staff     on public.child_consents for select using (public.is_management());
create policy child_cons_parent    on public.child_consents for select using (public.auth_role() = 'parent' and public.can_see_child(child_id));
create policy child_docs_staff     on public.child_documents for select using (public.is_management());
create policy child_log_staff      on public.child_change_log for select using (public.is_management());

-- Teachers get NOTHING from these tables directly; they see allergies only through class_allergies() below.

-- ---------------------------------------------------------------------------
-- Private storage for registration files
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('registrations', 'registrations', false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf']),
  ('child-files',   'child-files',   false, 5242880, array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'])
on conflict (id) do update set public = false, file_size_limit = 5242880,
  allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'];

-- Files uploaded with the public form: only admin, manager and owner can read them. (The form uploads through
-- short-lived signed upload links created by the server, which is why there is no insert policy.)
create policy registrations_read on storage.objects for select to authenticated
  using (bucket_id = 'registrations' and public.is_management());

-- A child's own files (for example the ID photo of a pickup person added later): the child's parents and management.
create policy child_files_read on storage.objects for select to authenticated
  using (bucket_id = 'child-files' and (public.is_management()
         or (public.auth_role() = 'parent' and public.can_see_child(((storage.foldername(name))[1])::uuid))));
create policy child_files_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'child-files' and (storage.foldername(name))[2] = 'pickups'
              and (public.is_management() or (public.auth_role() = 'parent' and public.can_see_child(((storage.foldername(name))[1])::uuid))));

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
-- Queue an email to an address that has no login yet (the applicant).
create function public.cka_enqueue_email_address(p_email text, p_lang text, p_template text, p_payload jsonb, p_dedupe text default null) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.email_outbox (user_id, to_email, language, template, payload, dedupe_key)
  values (null, lower(btrim(p_email)), case when p_lang = 'ar' then 'ar' else 'en' end, p_template, coalesce(p_payload, '{}'), p_dedupe)
  on conflict (dedupe_key) do nothing;
end $$;

create function public.cka_log_child_change(p_child uuid, p_kind text, p_summary text, p_old text, p_new text) returns void
language plpgsql security definer set search_path = public as $$
begin
  insert into public.child_change_log (child_id, kind, summary, old_value, new_value, changed_by, changed_by_name)
  values (p_child, p_kind, p_summary, p_old, p_new, auth.uid(), public.cka_actor_name());
end $$;

-- The people to tell when something about a child's health or pickup list changes: the class's teachers and the admins.
create function public.cka_class_staff_and_admins(p_child uuid) returns setof uuid
language sql stable security definer set search_path = public as $$
  select id from (
    select cl.head_teacher_id as id from public.children c join public.classes cl on cl.id = c.class_id where c.id = p_child
    union select sc.staff_id from public.children c join public.staff_classes sc on sc.class_id = c.class_id where c.id = p_child
    union select id from public.profiles where role = 'admin'
  ) x where id is not null and exists (select 1 from public.profiles p where p.id = x.id and p.active)
$$;

-- Rate limiting for the public form (server only). True while the caller is within the limit.
create function public.registration_rate_hit(p_key text, p_limit int) returns boolean
language plpgsql security definer set search_path = public as $$
declare c int;
begin
  insert into public.registration_rate (key, bucket, n) values (p_key, date_trunc('hour', now()), 1)
  on conflict (key, bucket) do update set n = public.registration_rate.n + 1 returning n into c;
  delete from public.registration_rate where bucket < now() - interval '2 days';
  return c <= p_limit;
end $$;

create function public.cka_is_email(p text) returns boolean language sql immutable as $$ select p ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' and length(p) <= 254 $$;
create function public.cka_is_phone(p text) returns boolean language sql immutable as $$ select p ~ '^[+0-9][0-9 ()+-]{6,19}$' $$;

-- ---------------------------------------------------------------------------
-- Submitting an application (server only; the public form posts to the server, which calls this)
-- ---------------------------------------------------------------------------
create function public.register_application(p jsonb) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  draft uuid; lang text; cname text; dob date; prog text; start_ date; photo text;
  prefix text; parents jsonb; pk jsonb; docs jsonb; d jsonb; i int; app public.registration_applications; cons jsonb; firstemail text;
begin
  if jsonb_typeof(p) <> 'object' then raise exception 'bad_request'; end if;
  begin draft := (p ->> 'draft_id')::uuid; exception when others then raise exception 'bad_request'; end;
  prefix := 'drafts/' || draft || '/';
  lang := case when p ->> 'language' = 'ar' then 'ar' else 'en' end;

  cname := btrim(coalesce(p #>> '{child,name}', ''));
  if length(cname) < 2 or length(cname) > 120 then raise exception 'invalid_child_name'; end if;
  begin dob := (p #>> '{child,dob}')::date; exception when others then raise exception 'invalid_child_dob'; end;
  if dob is null or dob > current_date or dob < current_date - interval '20 years' then raise exception 'invalid_child_dob'; end if;
  prog := p #>> '{child,programme}';
  if prog is null or prog not in ('nursery', 'preschool', 'after_school', 'camp') then raise exception 'invalid_programme'; end if;
  if nullif(p #>> '{child,preferred_start}', '') is not null then
    begin start_ := (p #>> '{child,preferred_start}')::date; exception when others then raise exception 'invalid_start_date'; end;
    if start_ < current_date - 30 or start_ > current_date + 800 then raise exception 'invalid_start_date'; end if;
  end if;
  photo := nullif(p #>> '{child,photo_path}', '');
  if photo is not null and (photo not like prefix || '%' or photo like '%..%') then raise exception 'invalid_file'; end if;

  parents := coalesce(p -> 'parents', '[]');
  if jsonb_typeof(parents) <> 'array' or jsonb_array_length(parents) < 1 or jsonb_array_length(parents) > 2 then raise exception 'invalid_parents'; end if;
  for i in 0 .. jsonb_array_length(parents) - 1 loop
    d := parents -> i;
    if length(btrim(coalesce(d ->> 'full_name', ''))) < 2 or length(d ->> 'full_name') > 120
       or not public.cka_is_phone(btrim(coalesce(d ->> 'phone', ''))) or not public.cka_is_email(lower(btrim(coalesce(d ->> 'email', ''))))
       or coalesce(d ->> 'relationship', '') not in ('mother', 'father', 'guardian', 'other') then
      raise exception 'invalid_parent_%', i + 1;
    end if;
  end loop;
  firstemail := lower(btrim(parents -> 0 ->> 'email'));

  cons := coalesce(p -> 'consents', '{}');
  if jsonb_typeof(cons -> 'photos_class') <> 'boolean' or jsonb_typeof(cons -> 'photos_social') <> 'boolean' or jsonb_typeof(cons -> 'outings') <> 'boolean'
     or jsonb_typeof(cons -> 'emergency_treatment') <> 'boolean' or jsonb_typeof(cons -> 'birthday_wall') <> 'boolean' then
    raise exception 'consents_incomplete';
  end if;
  if length(coalesce(p #>> '{health,allergies}', '')) > 2000 or length(coalesce(p #>> '{health,medical_conditions}', '')) > 2000
     or length(coalesce(p #>> '{health,medications}', '')) > 2000 then raise exception 'text_too_long'; end if;
  if nullif(p #>> '{health,doctor_phone}', '') is not null and not public.cka_is_phone(btrim(p #>> '{health,doctor_phone}')) then raise exception 'invalid_doctor_phone'; end if;

  pk := coalesce(p -> 'pickups', '[]');
  if jsonb_typeof(pk) <> 'array' or jsonb_array_length(pk) > 6 then raise exception 'invalid_pickups'; end if;
  for i in 0 .. jsonb_array_length(pk) - 1 loop
    d := pk -> i;
    if length(btrim(coalesce(d ->> 'full_name', ''))) < 2 or length(btrim(coalesce(d ->> 'relationship', ''))) < 2
       or not public.cka_is_phone(btrim(coalesce(d ->> 'phone', ''))) then raise exception 'invalid_pickup_%', i + 1; end if;
    if nullif(d ->> 'id_photo_path', '') is not null and ((d ->> 'id_photo_path') not like prefix || '%' or (d ->> 'id_photo_path') like '%..%') then raise exception 'invalid_file'; end if;
  end loop;

  docs := coalesce(p -> 'documents', '[]');
  if jsonb_typeof(docs) <> 'array' or jsonb_array_length(docs) > 6 then raise exception 'invalid_documents'; end if;
  for i in 0 .. jsonb_array_length(docs) - 1 loop
    d := docs -> i;
    if coalesce(d ->> 'kind', '') not in ('birth_certificate', 'vaccination_record', 'other')
       or (d ->> 'path') not like prefix || '%' or (d ->> 'path') like '%..%'
       or coalesce(d ->> 'mime_type', '') not in ('image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf')
       or coalesce((d ->> 'size_bytes')::int, 0) not between 1 and 5242880 then raise exception 'invalid_file'; end if;
  end loop;

  -- the same child, from the same email, within 30 days, is a duplicate
  if exists (select 1 from public.registration_applications a join public.registration_parents rp on rp.application_id = a.id and rp.position = 1
              where lower(a.child_name) = lower(cname) and a.child_dob = dob and lower(rp.email) = firstemail
                and a.created_at > now() - interval '30 days' and a.status <> 'declined') then
    raise exception 'duplicate_application';
  end if;

  insert into public.registration_applications (draft_id, language, child_name, child_dob, programme, preferred_start, child_photo_path,
      allergies, medical_conditions, medications, doctor_name, doctor_phone,
      consent_photos_class, consent_photos_social, consent_outings, consent_emergency_treatment, consent_birthday_wall)
  values (draft, lang, cname, dob, prog, start_, photo,
      nullif(btrim(p #>> '{health,allergies}'), ''), nullif(btrim(p #>> '{health,medical_conditions}'), ''), nullif(btrim(p #>> '{health,medications}'), ''),
      nullif(btrim(p #>> '{health,doctor_name}'), ''), nullif(btrim(p #>> '{health,doctor_phone}'), ''),
      (cons ->> 'photos_class')::boolean, (cons ->> 'photos_social')::boolean, (cons ->> 'outings')::boolean,
      (cons ->> 'emergency_treatment')::boolean, (cons ->> 'birthday_wall')::boolean)
  returning * into app;

  for i in 0 .. jsonb_array_length(parents) - 1 loop
    d := parents -> i;
    insert into public.registration_parents (application_id, position, full_name, phone, email, relationship)
    values (app.id, i + 1, btrim(d ->> 'full_name'), btrim(d ->> 'phone'), lower(btrim(d ->> 'email')), d ->> 'relationship');
  end loop;
  for i in 0 .. jsonb_array_length(pk) - 1 loop
    d := pk -> i;
    insert into public.registration_pickups (application_id, full_name, relationship, phone, id_photo_path)
    values (app.id, btrim(d ->> 'full_name'), btrim(d ->> 'relationship'), btrim(d ->> 'phone'), nullif(d ->> 'id_photo_path', ''));
  end loop;
  for i in 0 .. jsonb_array_length(docs) - 1 loop
    d := docs -> i;
    insert into public.registration_documents (application_id, kind, storage_path, file_name, mime_type, size_bytes)
    values (app.id, d ->> 'kind', d ->> 'path', left(d ->> 'file_name', 200), d ->> 'mime_type', (d ->> 'size_bytes')::int);
  end loop;
  insert into public.registration_events (application_id, kind, note) values (app.id, 'submitted', null);

  perform public.cka_enqueue_email_address(firstemail, lang, 'registration_received',
    jsonb_build_object('application_no', app.application_no, 'child_name', cname), 'reg-received:' || app.id);
  return jsonb_build_object('id', app.id, 'application_no', app.application_no);
end $$;

-- ---------------------------------------------------------------------------
-- Staff: list, open, change status, approve
-- ---------------------------------------------------------------------------
create function public.registration_list(p_status text default null)
returns table (id uuid, application_no bigint, status text, child_name text, child_dob date, programme text, preferred_start date,
               parent_name text, parent_phone text, parent_email text, created_at timestamptz, document_count int, has_birth_certificate boolean,
               has_vaccination_record boolean, child_id uuid)
language sql stable security definer set search_path = public as $$
  select a.id, a.application_no, a.status, a.child_name, a.child_dob, a.programme, a.preferred_start, rp.full_name, rp.phone, rp.email, a.created_at,
         (select count(*)::int from public.registration_documents d where d.application_id = a.id),
         exists (select 1 from public.registration_documents d where d.application_id = a.id and d.kind = 'birth_certificate'),
         exists (select 1 from public.registration_documents d where d.application_id = a.id and d.kind = 'vaccination_record'),
         a.child_id
  from public.registration_applications a
  left join public.registration_parents rp on rp.application_id = a.id and rp.position = 1
  where public.is_management() and (p_status is null or a.status = p_status)
  order by (a.status in ('approved', 'declined')), a.created_at desc
$$;

create function public.registration_get(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare out jsonb;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  select to_jsonb(a) || jsonb_build_object(
      'parents', coalesce((select jsonb_agg(to_jsonb(rp) order by rp.position) from public.registration_parents rp where rp.application_id = a.id), '[]'),
      'pickups', coalesce((select jsonb_agg(to_jsonb(k) order by k.full_name) from public.registration_pickups k where k.application_id = a.id), '[]'),
      'documents', coalesce((select jsonb_agg(to_jsonb(d) order by d.kind) from public.registration_documents d where d.application_id = a.id), '[]'),
      'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at) from public.registration_events e where e.application_id = a.id), '[]'),
      'class_name', (select name from public.classes where id = a.assigned_class_id))
    into out from public.registration_applications a where a.id = p_id;
  return out;
end $$;

create function public.registration_set_status(p_id uuid, p_status text, p_note text default null) returns void
language plpgsql security definer set search_path = public as $$
declare a public.registration_applications; note text := nullif(btrim(coalesce(p_note, '')), ''); ev uuid; em text;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if p_status not in ('new', 'missing_documents', 'tour_booked', 'waitlist', 'declined') then raise exception 'Use approve to approve an application'; end if;
  select * into a from public.registration_applications where id = p_id;
  if a.id is null then raise exception 'Not found'; end if;
  if a.status = 'approved' then raise exception 'This application has already been approved'; end if;
  if p_status in ('missing_documents', 'declined') and note is null then raise exception 'Please say what is missing, or the reason'; end if;
  update public.registration_applications set status = p_status, status_note = note, decided_by = case when p_status = 'declined' then auth.uid() end,
         decided_at = case when p_status = 'declined' then now() end where id = p_id;
  insert into public.registration_events (application_id, actor_id, actor_name, kind, note)
  values (p_id, auth.uid(), public.cka_actor_name(), p_status, note) returning id into ev;
  select email into em from public.registration_parents where application_id = p_id and position = 1;
  if p_status <> 'new' and em is not null then
    perform public.cka_enqueue_email_address(em, a.language, 'registration_update',
      jsonb_build_object('application_no', a.application_no, 'child_name', a.child_name, 'status', p_status, 'note', note), 'reg-status:' || ev);
  end if;
end $$;

-- Approve: creates the child's record in the chosen class, copies the health details, consents, pickup people
-- and documents, and reports who to invite. (The server then sends the portal invitations.)
create function public.approve_registration(p_id uuid, p_class uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare a public.registration_applications; cid uuid; k record; d record; parents jsonb; em text;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  select * into a from public.registration_applications where id = p_id for update;
  if a.id is null then raise exception 'Not found'; end if;
  if a.status in ('approved', 'declined') then raise exception 'This application is already %', a.status; end if;
  if not exists (select 1 from public.classes where id = p_class) then raise exception 'Choose a class'; end if;

  insert into public.children (full_name, date_of_birth, class_id) values (a.child_name, a.child_dob, p_class) returning id into cid;
  insert into public.child_health (child_id, allergies, medical_conditions, medications, doctor_name, doctor_phone, updated_by)
  values (cid, a.allergies, a.medical_conditions, a.medications, a.doctor_name, a.doctor_phone, auth.uid());
  insert into public.child_consents (child_id, photos_class, photos_social, outings, emergency_treatment, birthday_wall, updated_by)
  values (cid, a.consent_photos_class, a.consent_photos_social, a.consent_outings, a.consent_emergency_treatment, a.consent_birthday_wall, auth.uid());
  insert into public.child_pickups (child_id, full_name, relationship, phone, id_photo_path)
    select cid, full_name, relationship, phone, id_photo_path from public.registration_pickups where application_id = p_id;
  insert into public.child_documents (child_id, kind, storage_path, file_name, mime_type, size_bytes)
    select cid, kind, storage_path, file_name, mime_type, size_bytes from public.registration_documents where application_id = p_id;
  if a.child_photo_path is not null then
    insert into public.child_documents (child_id, kind, storage_path, file_name) values (cid, 'child_photo', a.child_photo_path, 'child photo');
  end if;
  perform public.cka_log_child_change(cid, 'created', 'Created from application #' || a.application_no, null, null);

  update public.registration_applications set status = 'approved', status_note = null, child_id = cid, assigned_class_id = p_class, decided_by = auth.uid(), decided_at = now() where id = p_id;
  insert into public.registration_events (application_id, actor_id, actor_name, kind, note) values (p_id, auth.uid(), public.cka_actor_name(), 'approved', null);

  select email into em from public.registration_parents where application_id = p_id and position = 1;
  if em is not null then
    perform public.cka_enqueue_email_address(em, a.language, 'registration_update',
      jsonb_build_object('application_no', a.application_no, 'child_name', a.child_name, 'status', 'approved'), 'reg-approved:' || p_id);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('position', position, 'full_name', full_name, 'phone', phone, 'email', email) order by position), '[]')
    into parents from public.registration_parents where application_id = p_id;
  return jsonb_build_object('child_id', cid, 'language', a.language, 'parents', parents);
end $$;

-- Server only: is there already a login for this email? (used to link a second child to an existing parent)
create function public.find_user_by_email(p_email text) returns table (id uuid, role text, active boolean)
language sql stable security definer set search_path = public as $$
  select u.id, p.role, p.active from auth.users u join public.profiles p on p.id = u.id where lower(u.email) = lower(btrim(p_email))
$$;

-- ---------------------------------------------------------------------------
-- Teachers: allergies for the children in their classes (and ONLY allergies)
-- ---------------------------------------------------------------------------
create function public.class_allergies()
returns table (child_id uuid, child_name text, class_name text, allergies text)
language sql stable security definer set search_path = public as $$
  select c.id, c.full_name, cl.name, nullif(btrim(h.allergies), '')
  from public.children c
  join public.classes cl on cl.id = c.class_id
  left join public.child_health h on h.child_id = c.id
  where c.active and (public.is_management() or public.teaches_class(c.class_id))
  order by cl.name, c.full_name
$$;

-- ---------------------------------------------------------------------------
-- Parents: update a child's allergies/health and pickup people (staff are told, the change is logged)
-- ---------------------------------------------------------------------------
create function public.parent_update_health(p_child uuid, p_allergies text, p_conditions text, p_medications text, p_doctor_name text, p_doctor_phone text) returns void
language plpgsql security definer set search_path = public as $$
declare old public.child_health; s uuid; ch uuid; summary text := '';
begin
  if public.auth_role() <> 'parent' or not public.can_see_child(p_child) then raise exception 'Not allowed'; end if;
  if length(coalesce(p_allergies, '')) > 2000 or length(coalesce(p_conditions, '')) > 2000 or length(coalesce(p_medications, '')) > 2000 then raise exception 'That is too long'; end if;
  if nullif(btrim(coalesce(p_doctor_phone, '')), '') is not null and not public.cka_is_phone(btrim(p_doctor_phone)) then raise exception 'Please check the doctor''s phone number'; end if;
  select * into old from public.child_health where child_id = p_child;
  if old.child_id is null then
    insert into public.child_health (child_id, updated_by) values (p_child, auth.uid()); select * into old from public.child_health where child_id = p_child;
  end if;
  if old.allergies is distinct from nullif(btrim(coalesce(p_allergies, '')), '') then summary := summary || 'Allergies. '; end if;
  if old.medical_conditions is distinct from nullif(btrim(coalesce(p_conditions, '')), '') then summary := summary || 'Medical conditions. '; end if;
  if old.medications is distinct from nullif(btrim(coalesce(p_medications, '')), '') then summary := summary || 'Medications. '; end if;
  if old.doctor_name is distinct from nullif(btrim(coalesce(p_doctor_name, '')), '') or old.doctor_phone is distinct from nullif(btrim(coalesce(p_doctor_phone, '')), '') then summary := summary || 'Doctor. '; end if;
  if summary = '' then return; end if;
  update public.child_health set allergies = nullif(btrim(coalesce(p_allergies, '')), ''), medical_conditions = nullif(btrim(coalesce(p_conditions, '')), ''),
         medications = nullif(btrim(coalesce(p_medications, '')), ''), doctor_name = nullif(btrim(coalesce(p_doctor_name, '')), ''),
         doctor_phone = nullif(btrim(coalesce(p_doctor_phone, '')), ''), updated_at = now(), updated_by = auth.uid() where child_id = p_child;
  perform public.cka_log_child_change(p_child, 'health', 'Parent updated: ' || btrim(summary),
    concat_ws(' | ', old.allergies, old.medical_conditions, old.medications), concat_ws(' | ', nullif(btrim(p_allergies), ''), nullif(btrim(p_conditions), ''), nullif(btrim(p_medications), '')));
  select id into ch from public.child_change_log where child_id = p_child order by created_at desc limit 1;
  for s in select * from public.cka_class_staff_and_admins(p_child) loop
    perform public.cka_enqueue_email(s, 'child_health_changed', jsonb_build_object('child_id', p_child), 'health:' || ch || ':' || s);
  end loop;
end $$;

create function public.parent_save_pickup(p_child uuid, p_pickup uuid, p_name text, p_relationship text, p_phone text, p_id_photo_path text default null, p_active boolean default true) returns uuid
language plpgsql security definer set search_path = public as $$
declare pid uuid := p_pickup; s uuid; ch uuid; photo text := nullif(btrim(coalesce(p_id_photo_path, '')), '');
begin
  if public.auth_role() <> 'parent' or not public.can_see_child(p_child) then raise exception 'Not allowed'; end if;
  if length(btrim(coalesce(p_name, ''))) < 2 or length(btrim(coalesce(p_relationship, ''))) < 2 or not public.cka_is_phone(btrim(coalesce(p_phone, ''))) then raise exception 'Please check the name, relationship and phone number'; end if;
  if photo is not null and (photo not like p_child::text || '/pickups/%' or photo like '%..%') then raise exception 'Invalid photo'; end if;
  if pid is null then
    if (select count(*) from public.child_pickups where child_id = p_child and active) >= 8 then raise exception 'You can list at most 8 people'; end if;
    insert into public.child_pickups (child_id, full_name, relationship, phone, id_photo_path, active)
    values (p_child, btrim(p_name), btrim(p_relationship), btrim(p_phone), photo, coalesce(p_active, true)) returning id into pid;
    perform public.cka_log_child_change(p_child, 'pickup', 'Parent added a pickup person: ' || btrim(p_name), null, btrim(p_name));
  else
    if not exists (select 1 from public.child_pickups where id = pid and child_id = p_child) then raise exception 'Not found'; end if;
    update public.child_pickups set full_name = btrim(p_name), relationship = btrim(p_relationship), phone = btrim(p_phone),
           id_photo_path = coalesce(photo, id_photo_path), active = coalesce(p_active, true) where id = pid;
    perform public.cka_log_child_change(p_child, 'pickup', case when coalesce(p_active, true) then 'Parent changed a pickup person: ' else 'Parent removed a pickup person: ' end || btrim(p_name), null, btrim(p_name));
  end if;
  select id into ch from public.child_change_log where child_id = p_child order by created_at desc limit 1;
  for s in select * from public.cka_class_staff_and_admins(p_child) loop
    perform public.cka_enqueue_email(s, 'child_pickup_changed', jsonb_build_object('child_id', p_child), 'pickup:' || ch || ':' || s);
  end loop;
  return pid;
end $$;

-- Grants: browsers may call the staff, teacher and parent functions; the server alone calls the rest.
revoke all on function
  public.cka_enqueue_email_address(text, text, text, jsonb, text), public.cka_log_child_change(uuid, text, text, text, text),
  public.cka_class_staff_and_admins(uuid), public.registration_rate_hit(text, int), public.register_application(jsonb), public.find_user_by_email(text),
  public.registration_list(text), public.registration_get(uuid), public.registration_set_status(uuid, text, text), public.approve_registration(uuid, uuid),
  public.class_allergies(), public.parent_update_health(uuid, text, text, text, text, text), public.parent_save_pickup(uuid, uuid, text, text, text, text, boolean)
from public, anon, authenticated;
grant execute on function public.registration_list(text), public.registration_get(uuid), public.registration_set_status(uuid, text, text), public.approve_registration(uuid, uuid),
  public.class_allergies(), public.parent_update_health(uuid, text, text, text, text, text), public.parent_save_pickup(uuid, uuid, text, text, text, text, boolean) to authenticated;

-- ============================================================
-- migrations/20261006121500_attendance.sql
-- ============================================================
-- Attendance and pickup (Prompt 12).
--
-- * The door screen: staff check each child in and out; the time is recorded.
-- * At check-out staff choose who is collecting from the child's authorised pickup list. Anyone not on the list
--   is recorded as an exception (the screen tells staff to keep the child and call the parent) and the parents,
--   the class staff and the admins are told.
-- * Parents report an absence or a late arrival (before 8 am for today, any time for a later day).
-- * Children not checked in by 9:30 with no notice are flagged to admin (checked by the scheduler).
-- * Pickups after 18:00 Cairo time are recorded as overtime minutes (the billing report reads them).
-- * Parents see their child's check-in and check-out times; teachers see their own class; admin sees everyone.
-- Browsers only READ these tables (row-level security); every change goes through a checked function.

-- ---------------------------------------------------------------------------
-- The clock. cka_now() is "now", except that tests can set app.now to travel in time.
-- ---------------------------------------------------------------------------
create function public.cka_now() returns timestamptz
language sql stable as $$ select coalesce(nullif(current_setting('app.now', true), '')::timestamptz, now()) $$;

create function public.cka_today() returns date
language sql stable as $$ select (public.cka_now() at time zone 'Africa/Cairo')::date $$;

-- Only the database's own functions use these two.
revoke all on function public.cka_now(), public.cka_today() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.attendance (
  id                    uuid primary key default gen_random_uuid(),
  child_id              uuid not null references public.children (id),
  att_date              date not null,
  checked_in_at         timestamptz not null,
  checked_in_by         uuid references public.profiles (id),
  checked_out_at        timestamptz,
  checked_out_by        uuid references public.profiles (id),
  collector_pickup_id   uuid references public.child_pickups (id),
  collector_name        text,
  collector_relationship text,
  off_list              boolean not null default false,
  off_list_note         text,
  overtime_minutes      integer not null default 0 check (overtime_minutes >= 0),
  unique (child_id, att_date),
  check (checked_out_at is null or checked_out_at >= checked_in_at)
);
create index attendance_date_idx on public.attendance (att_date);

-- A parent's notice about a day: an absence, or a late arrival.
create table public.attendance_notices (
  id                uuid primary key default gen_random_uuid(),
  child_id          uuid not null references public.children (id),
  notice_date       date not null,
  kind              text not null check (kind in ('absence', 'late')),
  expected_arrival  time,
  reason            text not null check (length(btrim(reason)) between 2 and 500),
  reported_by       uuid references public.profiles (id),
  reported_by_role  text not null default 'parent',
  reported_at       timestamptz not null default now(),
  unique (child_id, notice_date)
);

-- A record of everything done at the door (who, when, what), including corrections. Management only.
create table public.attendance_events (
  id          uuid primary key default gen_random_uuid(),
  child_id    uuid not null references public.children (id),
  att_date    date not null,
  kind        text not null,
  actor_id    uuid references public.profiles (id),
  actor_name  text,
  note        text,
  created_at  timestamptz not null default now()
);
create index attendance_events_child_idx on public.attendance_events (child_id, att_date);

-- "Not here by 9:30 and no notice": one row per child per day, so admin can log that they called the parent.
create table public.attendance_flags (
  child_id    uuid not null references public.children (id),
  att_date    date not null,
  flagged_at  timestamptz not null default now(),
  called_at   timestamptz,
  called_by   uuid references public.profiles (id),
  call_note   text,
  primary key (child_id, att_date)
);

alter table public.attendance          enable row level security;
alter table public.attendance_notices  enable row level security;
alter table public.attendance_events   enable row level security;
alter table public.attendance_flags    enable row level security;
revoke all on public.attendance, public.attendance_notices, public.attendance_events, public.attendance_flags from anon, authenticated;
grant select on public.attendance, public.attendance_notices, public.attendance_events, public.attendance_flags to authenticated;

-- can_see_child(): management sees every child, a teacher only their own class, a parent only their own children.
create policy attendance_select on public.attendance         for select using (public.can_see_child(child_id));
create policy att_notice_select on public.attendance_notices for select using (public.can_see_child(child_id));
create policy att_events_select on public.attendance_events  for select using (public.is_management());
create policy att_flags_select  on public.attendance_flags   for select using (public.is_management());

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
-- May the caller work the door for this child? Admin, manager, owner, or the child's own class teacher.
create function public.cka_door_allowed(p_child uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.auth_role() in ('admin', 'manager', 'owner', 'teacher'), false) and public.can_see_child(p_child)
$$;

create function public.cka_att_log(p_child uuid, p_date date, p_kind text, p_note text default null) returns void
language sql security definer set search_path = public as $$
  insert into public.attendance_events (child_id, att_date, kind, actor_id, actor_name, note)
  values (p_child, p_date, p_kind, auth.uid(), public.cka_actor_name(), p_note)
$$;

-- ---------------------------------------------------------------------------
-- The door screen: today's children, class by class
-- ---------------------------------------------------------------------------
create function public.door_list(p_date date default null)
returns table (child_id uuid, child_name text, class_id uuid, class_name text,
               checked_in_at timestamptz, checked_out_at timestamptz, collector_name text, off_list boolean, overtime_minutes int,
               notice_kind text, notice_reason text, notice_arrival time,
               flagged boolean, called_at timestamptz, call_note text)
language sql stable security definer set search_path = public as $$
  with d as (select coalesce(p_date, public.cka_today()) as day)
  select c.id, c.full_name, c.class_id, cl.name,
         a.checked_in_at, a.checked_out_at, a.collector_name, coalesce(a.off_list, false), coalesce(a.overtime_minutes, 0),
         n.kind, n.reason, n.expected_arrival,
         (d.day = public.cka_today() and public.cka_is_work_day(d.day) and a.id is null and n.id is null
            and (public.cka_now() at time zone 'Africa/Cairo')::time >= time '09:30' and (public.cka_now() at time zone 'Africa/Cairo')::time < time '18:00'),
         f.called_at, f.call_note
  from d
  join public.children c on c.active
  left join public.classes cl on cl.id = c.class_id
  left join public.attendance a on a.child_id = c.id and a.att_date = d.day
  left join public.attendance_notices n on n.child_id = c.id and n.notice_date = d.day
  left join public.attendance_flags f on f.child_id = c.id and f.att_date = d.day and public.is_management()
  where public.auth_role() in ('admin', 'manager', 'owner', 'teacher') and public.can_see_child(c.id)
  order by cl.name nulls last, c.full_name
$$;

-- The people allowed to collect one child, for the door staff (management and that child's class teacher).
-- Teachers get the pickup list ONLY through this function; they still cannot read health details or documents.
create function public.door_pickups(p_child uuid)
returns table (id uuid, full_name text, relationship text, phone text, id_photo_path text)
language sql stable security definer set search_path = public as $$
  select k.id, k.full_name, k.relationship, k.phone, k.id_photo_path
    from public.child_pickups k
   where k.child_id = p_child and k.active and public.cka_door_allowed(p_child)
   order by k.full_name
$$;

-- The parents' names and phone numbers, so the door staff can call them ("keep the child and call the parent").
create function public.door_parents(p_child uuid)
returns table (full_name text, phone text)
language sql stable security definer set search_path = public as $$
  select p.full_name, p.phone
    from public.parent_children pc join public.profiles p on p.id = pc.parent_id and p.active
   where pc.child_id = p_child and public.cka_door_allowed(p_child)
   order by p.full_name
$$;

-- The door staff of the child's class may open the pickup ID photos (and nothing else in the child's files).
create function public.cka_door_file(p_path text) returns boolean
language sql stable security definer set search_path = public as $$
  select case when (storage.foldername(p_path))[2] = 'pickups' and (storage.foldername(p_path))[1] ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then public.cka_door_allowed(((storage.foldername(p_path))[1])::uuid) else false end
$$;
create policy child_files_read_door on storage.objects for select to authenticated
  using (bucket_id = 'child-files' and public.cka_door_file(name));

create function public.door_check_in(p_child uuid) returns timestamptz
language plpgsql security definer set search_path = public as $$
declare day date := public.cka_today(); t timestamptz := public.cka_now();
begin
  if not public.cka_door_allowed(p_child) then raise exception 'Not allowed'; end if;
  if not exists (select 1 from public.children where id = p_child and active) then raise exception 'Not found'; end if;
  if exists (select 1 from public.attendance where child_id = p_child and att_date = day) then raise exception 'Already checked in today'; end if;
  insert into public.attendance (child_id, att_date, checked_in_at, checked_in_by) values (p_child, day, t, auth.uid());
  perform public.cka_att_log(p_child, day, 'check_in');
  return t;
end $$;

-- Check-out. Choose a person from the child's pickup list (p_pickup), or record someone who is NOT on the list
-- (name, relationship and a note saying who approved it and how: the screen has already told staff to keep the child and call the parent).
create function public.door_check_out(p_child uuid, p_pickup uuid default null, p_name text default null, p_relationship text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  day date := public.cka_today(); t timestamptz := public.cka_now();
  a public.attendance; pk public.child_pickups; ot int; is_off boolean := false; nm text; rel text; note text := nullif(btrim(coalesce(p_note, '')), ''); s uuid;
begin
  if not public.cka_door_allowed(p_child) then raise exception 'Not allowed'; end if;
  select * into a from public.attendance where child_id = p_child and att_date = day for update;
  if a.id is null then raise exception 'This child has not been checked in today'; end if;
  if a.checked_out_at is not null then raise exception 'Already checked out'; end if;

  if p_pickup is not null then
    select * into pk from public.child_pickups where id = p_pickup and child_id = p_child and active;
    if pk.id is null then raise exception 'That person is not on this child''s pickup list'; end if;
    nm := pk.full_name; rel := pk.relationship;
  else
    nm := btrim(coalesce(p_name, '')); rel := btrim(coalesce(p_relationship, ''));
    if length(nm) < 2 or length(rel) < 2 then raise exception 'off_list_needs_details'; end if;
    if note is null or length(note) < 3 then raise exception 'off_list_needs_parent_approval'; end if;
    is_off := true;
  end if;

  ot := greatest(0, floor(extract(epoch from (t - ((day + time '18:00') at time zone 'Africa/Cairo'))) / 60))::int;
  update public.attendance
     set checked_out_at = t, checked_out_by = auth.uid(), collector_pickup_id = pk.id, collector_name = nm, collector_relationship = rel,
         off_list = is_off, off_list_note = case when is_off then note end, overtime_minutes = ot
   where id = a.id;
  perform public.cka_att_log(p_child, day, case when is_off then 'check_out_off_list' else 'check_out' end, nm || ' (' || rel || ')' || coalesce(': ' || note, ''));

  if is_off then
    for s in select pc.parent_id from public.parent_children pc join public.profiles p on p.id = pc.parent_id and p.active where pc.child_id = p_child loop
      perform public.cka_enqueue_email(s, 'pickup_off_list_parent', jsonb_build_object('child_id', p_child), 'offlist:' || a.id || ':' || s);
    end loop;
    for s in select * from public.cka_class_staff_and_admins(p_child) loop
      perform public.cka_enqueue_email(s, 'pickup_off_list_staff', jsonb_build_object('child_id', p_child), 'offlist:' || a.id || ':' || s);
    end loop;
  end if;
  return jsonb_build_object('checked_out_at', t, 'overtime_minutes', ot, 'off_list', is_off);
end $$;

-- Fix a slip at the door (today only). Every correction is logged.
create function public.door_undo(p_child uuid, p_what text) returns void
language plpgsql security definer set search_path = public as $$
declare day date := public.cka_today(); a public.attendance;
begin
  if not public.cka_door_allowed(p_child) then raise exception 'Not allowed'; end if;
  select * into a from public.attendance where child_id = p_child and att_date = day for update;
  if a.id is null then raise exception 'This child has not been checked in today'; end if;
  if p_what = 'check_out' then
    if a.checked_out_at is null then raise exception 'This child has not been checked out'; end if;
    update public.attendance set checked_out_at = null, checked_out_by = null, collector_pickup_id = null, collector_name = null, collector_relationship = null,
           off_list = false, off_list_note = null, overtime_minutes = 0 where id = a.id;
    perform public.cka_att_log(p_child, day, 'undo_check_out');
  elsif p_what = 'check_in' then
    if a.checked_out_at is not null then raise exception 'Undo the check-out first'; end if;
    delete from public.attendance where id = a.id;
    perform public.cka_att_log(p_child, day, 'undo_check_in');
  else
    raise exception 'Unknown action';
  end if;
end $$;

-- Admin: "I called the parent" for a child who has not arrived and has no notice.
create function public.door_log_call(p_child uuid, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare day date := public.cka_today(); note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if note is null or length(note) < 2 then raise exception 'Please write what the parent said'; end if;
  if not exists (select 1 from public.children where id = p_child and active) then raise exception 'Not found'; end if;
  insert into public.attendance_flags (child_id, att_date, called_at, called_by, call_note) values (p_child, day, public.cka_now(), auth.uid(), note)
  on conflict (child_id, att_date) do update set called_at = excluded.called_at, called_by = excluded.called_by, call_note = excluded.call_note;
  perform public.cka_att_log(p_child, day, 'parent_called', note);
end $$;

-- ---------------------------------------------------------------------------
-- Parents: report an absence or a late arrival
-- ---------------------------------------------------------------------------
create function public.parent_report_attendance(p_child uuid, p_date date, p_kind text, p_reason text, p_arrival time default null) returns void
language plpgsql security definer set search_path = public as $$
declare today date := public.cka_today(); why text := btrim(coalesce(p_reason, ''));
begin
  if public.auth_role() <> 'parent' or not public.can_see_child(p_child) then raise exception 'Not allowed'; end if;
  if p_kind not in ('absence', 'late') then raise exception 'Unknown kind'; end if;
  if p_date is null or p_date < today or p_date > today + 60 then raise exception 'Please choose today or a day in the next 60 days'; end if;
  if not public.cka_is_work_day(p_date) then raise exception 'The academy is closed that day'; end if;
  if p_date = today and (public.cka_now() at time zone 'Africa/Cairo')::time >= time '08:00' then raise exception 'too_late_today'; end if;
  if length(why) < 2 or length(why) > 500 then raise exception 'Please give a short reason'; end if;
  if p_arrival is not null and (p_kind <> 'late' or p_arrival < time '08:00' or p_arrival > time '18:00') then raise exception 'Please check the arrival time'; end if;
  if p_date = today and exists (select 1 from public.attendance where child_id = p_child and att_date = p_date) then raise exception 'This child has already been checked in today'; end if;
  insert into public.attendance_notices (child_id, notice_date, kind, expected_arrival, reason, reported_by, reported_by_role)
  values (p_child, p_date, p_kind, p_arrival, why, auth.uid(), 'parent')
  on conflict (child_id, notice_date) do update set kind = excluded.kind, expected_arrival = excluded.expected_arrival, reason = excluded.reason,
         reported_by = excluded.reported_by, reported_at = now();
  perform public.cka_att_log(p_child, p_date, 'notice_' || p_kind, null);
end $$;

create function public.parent_cancel_attendance_notice(p_child uuid, p_date date) returns void
language plpgsql security definer set search_path = public as $$
declare today date := public.cka_today();
begin
  if public.auth_role() <> 'parent' or not public.can_see_child(p_child) then raise exception 'Not allowed'; end if;
  if p_date < today or (p_date = today and (public.cka_now() at time zone 'Africa/Cairo')::time >= time '08:00') then raise exception 'too_late_today'; end if;
  delete from public.attendance_notices where child_id = p_child and notice_date = p_date and reported_by_role = 'parent';
  perform public.cka_att_log(p_child, p_date, 'notice_cancelled', null);
end $$;

-- ---------------------------------------------------------------------------
-- The 9:30 check (server only; run by the scheduler every 15 minutes)
-- ---------------------------------------------------------------------------
create function public.cka_run_attendance_check(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l timestamp := p_now at time zone 'Africa/Cairo'; day date := l::date; added int := 0; a uuid; sent int := 0;
begin
  if not public.cka_is_work_day(day) or l::time < time '09:30' or l::time >= time '18:00' then
    return jsonb_build_object('flagged', 0, 'emails', 0, 'checked', false);
  end if;
  insert into public.attendance_flags (child_id, att_date, flagged_at)
  select c.id, day, p_now from public.children c
   where c.active and c.class_id is not null
     and not exists (select 1 from public.attendance x where x.child_id = c.id and x.att_date = day)
     and not exists (select 1 from public.attendance_notices n where n.child_id = c.id and n.notice_date = day)
  on conflict do nothing;
  get diagnostics added = row_count;
  if added > 0 then
    for a in select id from public.profiles where role = 'admin' and active loop
      perform public.cka_enqueue_email(a, 'attendance_missing', jsonb_build_object('count', added), 'att-missing:' || day || ':' || a || ':' || (extract(epoch from p_now)::bigint / 900));
      sent := sent + 1;
    end loop;
  end if;
  return jsonb_build_object('flagged', added, 'emails', sent, 'checked', true);
end $$;

-- ---------------------------------------------------------------------------
-- Reports: attendance by class and by child for any period, and the overtime that feeds billing (management only)
-- ---------------------------------------------------------------------------
create function public.attendance_report(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare cutoff date; out jsonb;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 366 then raise exception 'Please choose a period of up to one year'; end if;
  -- days still in progress are not counted as "not reported": only completed days (today counts after closing time)
  cutoff := case when (public.cka_now() at time zone 'Africa/Cairo')::time >= time '18:00' then public.cka_today() else public.cka_today() - 1 end;
  with kids as (
    select c.id, c.full_name, c.class_id, coalesce(cl.name, '') as class_name, (c.created_at at time zone 'Africa/Cairo')::date as since
      from public.children c left join public.classes cl on cl.id = c.class_id where c.active
  ), days as (
    select k.id as child_id, g::date as d from kids k, generate_series(p_from, least(p_to, cutoff), interval '1 day') g
     where public.cka_is_work_day(g::date) and g::date >= k.since
  ), per as (
    select k.id as child_id, k.full_name, k.class_id, k.class_name,
           (select count(*) from days x where x.child_id = k.id)::int as school_days,
           (select count(*) from days x join public.attendance a on a.child_id = x.child_id and a.att_date = x.d where x.child_id = k.id)::int as present_days,
           (select count(*) from days x join public.attendance_notices n on n.child_id = x.child_id and n.notice_date = x.d and n.kind = 'absence'
              where x.child_id = k.id and not exists (select 1 from public.attendance a where a.child_id = x.child_id and a.att_date = x.d))::int as absent_reported,
           (select count(*) from public.attendance_notices n where n.child_id = k.id and n.kind = 'late' and n.notice_date between p_from and p_to)::int as late_notices,
           (select coalesce(sum(a.overtime_minutes), 0) from public.attendance a where a.child_id = k.id and a.att_date between p_from and p_to)::int as overtime_minutes,
           (select count(*) from public.attendance a where a.child_id = k.id and a.att_date between p_from and p_to and a.overtime_minutes > 0)::int as overtime_days
      from kids k
  )
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'by_child', coalesce((select jsonb_agg(jsonb_build_object('child_id', child_id, 'child_name', full_name, 'class_name', class_name, 'school_days', school_days,
          'present_days', present_days, 'absent_reported', absent_reported, 'not_reported', greatest(0, school_days - present_days - absent_reported),
          'late_notices', late_notices, 'overtime_minutes', overtime_minutes) order by class_name, full_name) from per), '[]'),
    'by_class', coalesce((select jsonb_agg(x order by x ->> 'class_name') from (
        select jsonb_build_object('class_name', class_name, 'children', count(*), 'school_days', sum(school_days), 'present_days', sum(present_days),
               'absent_reported', sum(absent_reported), 'not_reported', sum(greatest(0, school_days - present_days - absent_reported)),
               'late_notices', sum(late_notices), 'overtime_minutes', sum(overtime_minutes)) as x
          from per group by class_name) q), '[]'),
    'overtime', coalesce((select jsonb_agg(jsonb_build_object('child_id', child_id, 'child_name', full_name, 'class_name', class_name, 'days', overtime_days, 'minutes', overtime_minutes,
          'parents', coalesce((select string_agg(p.full_name, ', ' order by p.full_name) from public.parent_children pc join public.profiles p on p.id = pc.parent_id where pc.child_id = per.child_id), ''))
          order by overtime_minutes desc, full_name) from per where overtime_minutes > 0), '[]')
  ) into out;
  return out;
end $$;

-- Grants: browsers may run the door, parent and report functions; only the server runs the 9:30 check.
revoke all on function
  public.cka_door_allowed(uuid), public.cka_door_file(text), public.cka_att_log(uuid, date, text, text), public.door_list(date), public.door_pickups(uuid), public.door_parents(uuid), public.door_check_in(uuid),
  public.door_check_out(uuid, uuid, text, text, text), public.door_undo(uuid, text), public.door_log_call(uuid, text),
  public.parent_report_attendance(uuid, date, text, text, time), public.parent_cancel_attendance_notice(uuid, date),
  public.cka_run_attendance_check(timestamptz), public.attendance_report(date, date)
from public, anon, authenticated;
grant execute on function public.cka_door_file(text), public.door_list(date), public.door_pickups(uuid), public.door_parents(uuid), public.door_check_in(uuid), public.door_check_out(uuid, uuid, text, text, text), public.door_undo(uuid, text),
  public.door_log_call(uuid, text), public.parent_report_attendance(uuid, date, text, text, time), public.parent_cancel_attendance_notice(uuid, date),
  public.attendance_report(date, date) to authenticated;
grant execute on function public.cka_run_attendance_check(timestamptz) to service_role;

-- ============================================================
-- migrations/20261006121600_daily_reports.sql
-- ============================================================
-- Daily reports (Prompt 13, with the owner-approved changes of Prompt 21).
--
-- Teachers tap entries during the day for the children who are checked in: lunch (more, all, half, little, none),
-- water (cups), milk (ml), sleep (minutes), diaper changes, stools, temperature when needed, mood, and one personal
-- sentence. "Kindly send for tomorrow" (diapers, wipes, shower gel, cotton, extra clothes, other) is set per child.
-- Reports stay private drafts until they are sent (all together, or automatically at a set time before pickup);
-- after that only admin, manager or owner can change one, and every change is recorded.
-- A temperature of 38.0 or above alerts the class staff and the admins. Browsers only READ these tables.

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------
create table public.daily_reports (
  id               uuid primary key default gen_random_uuid(),
  child_id         uuid not null references public.children (id),
  report_date      date not null,
  lunch            text check (lunch in ('more', 'all', 'half', 'little', 'none')),
  water_cups       integer check (water_cups between 0 and 30),
  milk_ml          integer check (milk_ml between 0 and 2000),
  sleep_minutes    integer check (sleep_minutes between 0 and 720),
  diaper_changes   integer check (diaper_changes between 0 and 30),
  stool_count      integer check (stool_count between 0 and 30),
  temperature      numeric(3, 1) check (temperature between 34 and 43),
  mood             text check (mood in ('happy', 'calm', 'tired', 'upset')),
  personal_note    text check (length(personal_note) <= 1000),
  status           text not null default 'draft' check (status in ('draft', 'sent')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  updated_by       uuid references public.profiles (id),
  sent_at          timestamptz,
  sent_by          uuid references public.profiles (id),          -- null when it was sent automatically
  unique (child_id, report_date)
);
create index daily_reports_date_idx on public.daily_reports (report_date);

-- Changes to a report AFTER it was sent (admin, manager, owner only): who, why, and exactly what changed.
create table public.daily_report_edits (
  id           uuid primary key default gen_random_uuid(),
  report_id    uuid not null references public.daily_reports (id),
  editor_id    uuid references public.profiles (id),
  editor_name  text,
  reason       text not null,
  before       jsonb not null,
  after        jsonb not null,
  created_at   timestamptz not null default now()
);

-- "Kindly send for tomorrow": things a family should bring on the child's next school day.
create table public.send_requests (
  id          uuid primary key default gen_random_uuid(),
  child_id    uuid not null references public.children (id),
  for_date    date not null,
  items       text[] not null check (items <@ array['diapers', 'wipes', 'shower_gel', 'cotton', 'extra_clothes', 'other'] and cardinality(items) > 0),
  other_text  text check (length(other_text) <= 200),
  published   boolean not null default false,                   -- families see it once the child's report has been sent
  created_by  uuid references public.profiles (id),
  created_at  timestamptz not null default now(),
  unique (child_id, for_date)
);

-- One row: should reports go out by themselves, and when?
create table public.report_settings (
  id             boolean primary key default true check (id),
  auto_send      boolean not null default true,
  auto_send_time time not null default '16:30',
  updated_by     uuid references public.profiles (id)
);
insert into public.report_settings (id) values (true);

alter table public.daily_reports      enable row level security;
alter table public.daily_report_edits enable row level security;
alter table public.send_requests      enable row level security;
alter table public.report_settings    enable row level security;
revoke all on public.daily_reports, public.daily_report_edits, public.send_requests, public.report_settings from anon, authenticated;
grant select on public.daily_reports, public.daily_report_edits, public.send_requests, public.report_settings to authenticated;

-- Parents see only SENT reports about their own children; the class teacher and management also see drafts.
create policy dr_select   on public.daily_reports      for select using (public.can_see_child(child_id) and (status = 'sent' or public.auth_role() <> 'parent'));
create policy dre_select  on public.daily_report_edits for select using (public.is_management());
create policy sr_select   on public.send_requests      for select using (public.can_see_child(child_id) and (published or public.auth_role() <> 'parent'));
create policy rs_select   on public.report_settings    for select using (public.is_management());

-- ---------------------------------------------------------------------------
-- Helpers (internal)
-- ---------------------------------------------------------------------------
create function public.cka_report_has_content(r public.daily_reports) returns boolean
language sql immutable as $$
  select r.lunch is not null or r.water_cups is not null or r.milk_ml is not null or r.sleep_minutes is not null or r.diaper_changes is not null
      or r.stool_count is not null or r.temperature is not null or r.mood is not null or nullif(btrim(coalesce(r.personal_note, '')), '') is not null
$$;

-- Create or update a report from a JSON object of fields. Only keys that are present are changed; null clears one.
create function public.cka_report_upsert(p_child uuid, p_date date, f jsonb) returns public.daily_reports
language plpgsql security definer set search_path = public as $$
declare r public.daily_reports; s uuid; had_fever boolean;
begin
  select * into r from public.daily_reports where child_id = p_child and report_date = p_date;
  if r.id is null then
    insert into public.daily_reports (child_id, report_date, updated_by) values (p_child, p_date, auth.uid()) returning * into r;
  end if;
  had_fever := coalesce(r.temperature >= 38, false);
  begin
    update public.daily_reports set
      lunch          = case when f ? 'lunch' then nullif(f ->> 'lunch', '') else lunch end,
      water_cups     = case when f ? 'water_cups' then (f ->> 'water_cups')::int else water_cups end,
      milk_ml        = case when f ? 'milk_ml' then (f ->> 'milk_ml')::int else milk_ml end,
      sleep_minutes  = case when f ? 'sleep_minutes' then (f ->> 'sleep_minutes')::int else sleep_minutes end,
      diaper_changes = case when f ? 'diaper_changes' then (f ->> 'diaper_changes')::int else diaper_changes end,
      stool_count    = case when f ? 'stool_count' then (f ->> 'stool_count')::int else stool_count end,
      temperature    = case when f ? 'temperature' then (f ->> 'temperature')::numeric else temperature end,
      mood           = case when f ? 'mood' then nullif(f ->> 'mood', '') else mood end,
      personal_note  = case when f ? 'personal_note' then nullif(btrim(f ->> 'personal_note'), '') else personal_note end,
      updated_at = now(), updated_by = auth.uid()
     where id = r.id returning * into r;
  exception when check_violation or invalid_text_representation or numeric_value_out_of_range then
    raise exception 'invalid_report_value';
  end;
  -- a fever alerts the class staff and the admins once per report (the email carries no names or numbers)
  if r.temperature >= 38 and not had_fever then
    for s in select * from public.cka_class_staff_and_admins(p_child) loop
      perform public.cka_enqueue_email(s, 'fever_alert', jsonb_build_object('child_id', p_child), 'fever:' || r.id || ':' || s);
    end loop;
  end if;
  return r;
end $$;

-- Mark one report as sent and tell the parents (no details in the email).
create function public.cka_report_send_one(p_report uuid, p_by uuid) returns void
language plpgsql security definer set search_path = public as $$
declare r public.daily_reports; s uuid;
begin
  update public.daily_reports set status = 'sent', sent_at = now(), sent_by = p_by where id = p_report and status = 'draft' returning * into r;
  if r.id is null then return; end if;
  update public.send_requests set published = true where child_id = r.child_id and for_date = public.cka_next_work_day(r.report_date);
  for s in select pc.parent_id from public.parent_children pc join public.profiles p on p.id = pc.parent_id and p.active where pc.child_id = r.child_id loop
    perform public.cka_enqueue_email(s, 'daily_report_ready', jsonb_build_object('child_id', r.child_id), 'report:' || r.id || ':' || s);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- The teacher's sheet: today's checked-in children (and anyone who already has a report)
-- ---------------------------------------------------------------------------
create function public.report_sheet(p_date date default null)
returns table (child_id uuid, child_name text, class_id uuid, class_name text, allergies text,
               report_id uuid, status text, lunch text, water_cups int, milk_ml int, sleep_minutes int, diaper_changes int, stool_count int,
               temperature numeric, mood text, personal_note text, sent_at timestamptz,
               send_items text[], send_other text, has_content boolean, checked_out boolean)
language sql stable security definer set search_path = public as $$
  with d as (select coalesce(p_date, public.cka_today()) as day)
  select c.id, c.full_name, c.class_id, cl.name, nullif(btrim(h.allergies), ''),
         r.id, r.status, r.lunch, r.water_cups, r.milk_ml, r.sleep_minutes, r.diaper_changes, r.stool_count, r.temperature, r.mood, r.personal_note, r.sent_at,
         sr.items, sr.other_text, coalesce(public.cka_report_has_content(r), false), a.checked_out_at is not null
    from d
    join public.children c on c.active
    left join public.classes cl on cl.id = c.class_id
    left join public.child_health h on h.child_id = c.id
    left join public.attendance a on a.child_id = c.id and a.att_date = d.day
    left join public.daily_reports r on r.child_id = c.id and r.report_date = d.day
    left join public.send_requests sr on sr.child_id = c.id and sr.for_date = public.cka_next_work_day(d.day)
   where public.auth_role() in ('admin', 'manager', 'owner', 'teacher') and public.can_see_child(c.id) and (a.id is not null or r.id is not null)
   order by cl.name nulls last, c.full_name
$$;

-- Save entries for one or many children at once ("the whole class ate lunch"). Only for children who are checked in today.
create function public.report_save_many(p_children uuid[], p_fields jsonb) returns int
language plpgsql security definer set search_path = public as $$
declare day date := public.cka_today(); c uuid; n int := 0; st text;
begin
  if p_children is null or cardinality(p_children) = 0 or cardinality(p_children) > 60 then raise exception 'Choose between 1 and 60 children'; end if;
  if p_fields is null or jsonb_typeof(p_fields) <> 'object' then raise exception 'invalid_report_value'; end if;
  foreach c in array p_children loop
    if not public.cka_door_allowed(c) then raise exception 'Not allowed'; end if;
    if not exists (select 1 from public.attendance where child_id = c and att_date = day) then raise exception 'not_checked_in'; end if;
    select status into st from public.daily_reports where child_id = c and report_date = day;
    if st = 'sent' then raise exception 'already_sent'; end if;
    perform public.cka_report_upsert(c, day, p_fields);
    n := n + 1;
  end loop;
  return n;
end $$;

-- Send today's reports now: the given children, or everyone the caller may report on. Empty reports are not sent.
create function public.report_send(p_children uuid[] default null) returns int
language plpgsql security definer set search_path = public as $$
declare day date := public.cka_today(); r record; n int := 0;
begin
  if not coalesce(public.auth_role() in ('admin', 'manager', 'owner', 'teacher'), false) then raise exception 'Not allowed'; end if;
  for r in select * from public.daily_reports d where d.report_date = day and d.status = 'draft' and public.cka_report_has_content(d)
              and (p_children is null or d.child_id = any (p_children)) and public.cka_door_allowed(d.child_id) loop
    perform public.cka_report_send_one(r.id, auth.uid());
    n := n + 1;
  end loop;
  return n;
end $$;

-- "Kindly send for tomorrow" for one child (empty list removes it). Applies to the next school day.
create function public.send_request_save(p_child uuid, p_items text[], p_other text default null) returns void
language plpgsql security definer set search_path = public as $$
declare d date := public.cka_next_work_day(public.cka_today()); other text := nullif(btrim(coalesce(p_other, '')), ''); pub boolean;
begin
  if not public.cka_door_allowed(p_child) then raise exception 'Not allowed'; end if;
  if p_items is null or cardinality(p_items) = 0 then
    delete from public.send_requests where child_id = p_child and for_date = d;
    return;
  end if;
  if not (p_items <@ array['diapers', 'wipes', 'shower_gel', 'cotton', 'extra_clothes', 'other']) then raise exception 'Unknown item'; end if;
  if 'other' = any (p_items) and other is null then raise exception 'Please say what to send'; end if;
  pub := exists (select 1 from public.daily_reports where child_id = p_child and report_date = public.cka_today() and status = 'sent');
  insert into public.send_requests (child_id, for_date, items, other_text, published, created_by)
  values (p_child, d, p_items, case when 'other' = any (p_items) then other end, pub, auth.uid())
  on conflict (child_id, for_date) do update set items = excluded.items, other_text = excluded.other_text, created_by = excluded.created_by;
end $$;

-- Admin, manager, owner: change a report AFTER it was sent. The reason is required and the change is recorded.
create function public.report_edit_sent(p_report uuid, p_fields jsonb, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare r public.daily_reports; b jsonb; a jsonb; why text := btrim(coalesce(p_reason, ''));
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if length(why) < 3 then raise exception 'Please say why you are changing a sent report'; end if;
  select * into r from public.daily_reports where id = p_report;
  if r.id is null then raise exception 'Not found'; end if;
  if r.status <> 'sent' then raise exception 'This report has not been sent yet'; end if;
  b := to_jsonb(r) - 'id' - 'child_id' - 'report_date' - 'status' - 'created_at' - 'updated_at' - 'updated_by' - 'sent_at' - 'sent_by';
  r := public.cka_report_upsert(r.child_id, r.report_date, p_fields);
  a := to_jsonb(r) - 'id' - 'child_id' - 'report_date' - 'status' - 'created_at' - 'updated_at' - 'updated_by' - 'sent_at' - 'sent_by';
  if a = b then return; end if;
  insert into public.daily_report_edits (report_id, editor_id, editor_name, reason, before, after) values (r.id, auth.uid(), public.cka_actor_name(), why, b, a);
end $$;

-- ---------------------------------------------------------------------------
-- Admin and owner: how are today's reports going?
-- ---------------------------------------------------------------------------
create function public.report_overview(p_date date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare day date := coalesce(p_date, public.cka_today()); out jsonb;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  select jsonb_build_object(
    'date', day,
    'present', (select count(*) from public.attendance where att_date = day),
    'sent', (select count(*) from public.daily_reports r where r.report_date = day and r.status = 'sent'),
    'ready', (select count(*) from public.daily_reports r where r.report_date = day and r.status = 'draft' and public.cka_report_has_content(r)),
    'not_started', (select count(*) from public.attendance a where a.att_date = day
                      and not exists (select 1 from public.daily_reports r where r.child_id = a.child_id and r.report_date = day and public.cka_report_has_content(r))),
    'missing_note', coalesce((select jsonb_agg(jsonb_build_object('child_id', c.id, 'child_name', c.full_name, 'class_name', coalesce(cl.name, '')) order by cl.name, c.full_name)
                      from public.attendance a join public.children c on c.id = a.child_id left join public.classes cl on cl.id = c.class_id
                     where a.att_date = day and not exists (select 1 from public.daily_reports r where r.child_id = c.id and r.report_date = day and nullif(btrim(coalesce(r.personal_note, '')), '') is not null)), '[]'),
    'fever', coalesce((select jsonb_agg(jsonb_build_object('child_id', c.id, 'child_name', c.full_name, 'class_name', coalesce(cl.name, ''), 'temperature', r.temperature) order by r.temperature desc)
                      from public.daily_reports r join public.children c on c.id = r.child_id left join public.classes cl on cl.id = c.class_id
                     where r.report_date = day and r.temperature >= 38), '[]'),
    'settings', (select jsonb_build_object('auto_send', auto_send, 'auto_send_time', to_char(auto_send_time, 'HH24:MI')) from public.report_settings)
  ) into out;
  return out;
end $$;

create function public.report_settings_save(p_auto boolean, p_time time) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if p_time is null or p_time < time '12:00' or p_time > time '17:45' then raise exception 'Please choose a time between 12:00 and 17:45'; end if;
  update public.report_settings set auto_send = coalesce(p_auto, true), auto_send_time = p_time, updated_by = auth.uid();
end $$;

-- ---------------------------------------------------------------------------
-- The scheduler (server only, every 15 minutes): the 4 pm nudge for personal notes, and the automatic send
-- ---------------------------------------------------------------------------
create function public.cka_run_report_check(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = public as $$
declare l timestamp := p_now at time zone 'Africa/Cairo'; day date := l::date; s record; r record; reminders int := 0; sent int := 0; cfg public.report_settings; cnt int;
begin
  if not public.cka_is_work_day(day) or l::time < time '16:00' or l::time >= time '18:00' then
    return jsonb_build_object('checked', false, 'reminders', 0, 'sent', 0);
  end if;
  -- teachers whose present children still lack a personal sentence
  for s in select p.id as teacher from public.profiles p where p.role = 'teacher' and p.active loop
    select count(*) into cnt from public.attendance a join public.children c on c.id = a.child_id
     where a.att_date = day and c.class_id is not null
       and (c.class_id in (select class_id from public.staff_classes where staff_id = s.teacher) or c.class_id in (select id from public.classes where head_teacher_id = s.teacher))
       and not exists (select 1 from public.daily_reports d where d.child_id = c.id and d.report_date = day and nullif(btrim(coalesce(d.personal_note, '')), '') is not null);
    if cnt > 0 then
      perform public.cka_enqueue_email(s.teacher, 'report_note_reminder', jsonb_build_object('count', cnt), 'reportnote:' || day || ':' || s.teacher);
      reminders := reminders + 1;
    end if;
  end loop;
  -- automatic send
  select * into cfg from public.report_settings;
  if cfg.auto_send and l::time >= cfg.auto_send_time then
    for r in select id from public.daily_reports d where d.report_date = day and d.status = 'draft' and public.cka_report_has_content(d) loop
      perform public.cka_report_send_one(r.id, null);
      sent := sent + 1;
    end loop;
  end if;
  return jsonb_build_object('checked', true, 'reminders', reminders, 'sent', sent);
end $$;

-- Grants: browsers run the report screens; only the server runs the scheduled check and the internal helpers.
revoke all on function
  public.cka_report_has_content(public.daily_reports), public.cka_report_upsert(uuid, date, jsonb), public.cka_report_send_one(uuid, uuid),
  public.report_sheet(date), public.report_save_many(uuid[], jsonb), public.report_send(uuid[]), public.send_request_save(uuid, text[], text),
  public.report_edit_sent(uuid, jsonb, text), public.report_overview(date), public.report_settings_save(boolean, time), public.cka_run_report_check(timestamptz)
from public, anon, authenticated;
grant execute on function public.report_sheet(date), public.report_save_many(uuid[], jsonb), public.report_send(uuid[]), public.send_request_save(uuid, text[], text),
  public.report_edit_sent(uuid, jsonb, text), public.report_overview(date), public.report_settings_save(boolean, time) to authenticated;
grant execute on function public.cka_run_report_check(timestamptz) to service_role;

-- ============================================================
-- migrations/20261006121700_announcements.sql
-- ============================================================
-- Announcements, notification choices and push (Prompt 14, part 1).
--
-- * Admin posts news to everyone, one class, or chosen families, in Arabic and English, with an optional image or PDF
--   and an "important" flag. Parents see only what is meant for them; admin sees who has read it.
-- * Important announcements remind the families who have not opened them after 24 hours.
-- * Every notification is also an email; parents choose which kinds they want. Safety messages (accident reports, safety
--   reviews) cannot be switched off. Browsers also get a push "You have a new update" with no private details.

-- ---------------------------------------------------------------------------
-- What each parent wants to hear about
-- ---------------------------------------------------------------------------
create table public.notification_prefs (
  user_id        uuid primary key references public.profiles (id),
  reports        boolean not null default true,
  announcements  boolean not null default true,
  events         boolean not null default true,
  cases          boolean not null default true,
  updated_at     timestamptz not null default now()
);
alter table public.notification_prefs enable row level security;
revoke all on public.notification_prefs from anon, authenticated;
grant select on public.notification_prefs to authenticated;
create policy prefs_own on public.notification_prefs for select using (user_id = auth.uid());

create function public.notification_prefs_save(p_reports boolean, p_announcements boolean, p_events boolean, p_cases boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() is null then raise exception 'Not allowed'; end if;
  insert into public.notification_prefs (user_id, reports, announcements, events, cases)
  values (auth.uid(), coalesce(p_reports, true), coalesce(p_announcements, true), coalesce(p_events, true), coalesce(p_cases, true))
  on conflict (user_id) do update set reports = excluded.reports, announcements = excluded.announcements, events = excluded.events,
         cases = excluded.cases, updated_at = now();
end $$;

-- The email queue now respects those choices (the kinds that protect a child's safety always go out).
create or replace function public.cka_enqueue_email(p_user uuid, p_template text, p_payload jsonb, p_dedupe text default null) returns void
language plpgsql security definer set search_path = public as $$
declare e text; lang text; cat text; wanted boolean;
begin
  select u.email, p.language into e, lang
    from auth.users u join public.profiles p on p.id = u.id
   where u.id = p_user and p.active;
  if e is null then return; end if;
  cat := case when p_template = 'daily_report_ready' then 'reports'
              when p_template like 'announcement%' then 'announcements'
              when p_template like 'event\_%' then 'events'
              when p_template in ('received', 'acknowledged', 'update_added', 'urgency_changed', 'resolved') then 'cases'
              else null end;
  if cat is not null then
    select case cat when 'reports' then reports when 'announcements' then announcements when 'events' then events else cases end
      into wanted from public.notification_prefs where user_id = p_user;
    if found and wanted is false then return; end if;
  end if;
  insert into public.email_outbox (user_id, to_email, language, template, payload, dedupe_key)
  values (p_user, e, lang, p_template, coalesce(p_payload, '{}'), p_dedupe)
  on conflict (dedupe_key) do nothing;
end $$;

-- ---------------------------------------------------------------------------
-- Push subscriptions (browsers register; only the server reads them to send)
-- ---------------------------------------------------------------------------
create table public.push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id),
  endpoint    text not null unique check (length(endpoint) between 20 and 1000),
  p256dh      text not null,
  auth        text not null,
  created_at  timestamptz not null default now()
);
-- Remember which queued notifications have already been pushed to the person's devices.
alter table public.email_outbox add column pushed_at timestamptz;

alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from anon, authenticated;

create function public.push_subscribe(p_endpoint text, p_p256dh text, p_auth text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() is null then raise exception 'Not allowed'; end if;
  if p_endpoint !~ '^https://' or length(coalesce(p_p256dh, '')) < 20 or length(coalesce(p_auth, '')) < 8 then raise exception 'Invalid subscription'; end if;
  insert into public.push_subscriptions (user_id, endpoint, p256dh, auth) values (auth.uid(), p_endpoint, p_p256dh, p_auth)
  on conflict (endpoint) do update set user_id = excluded.user_id, p256dh = excluded.p256dh, auth = excluded.auth;
end $$;

create function public.push_unsubscribe(p_endpoint text) returns void
language plpgsql security definer set search_path = public as $$
begin
  delete from public.push_subscriptions where endpoint = p_endpoint and user_id = auth.uid();
end $$;

-- ---------------------------------------------------------------------------
-- Announcements
-- ---------------------------------------------------------------------------
create table public.announcements (
  id               uuid primary key default gen_random_uuid(),
  title_en         text,
  title_ar         text,
  body_en          text,
  body_ar          text,
  audience         text not null check (audience in ('all', 'class', 'families')),
  class_id         uuid references public.classes (id),
  important        boolean not null default false,
  kind             text not null default 'news' check (kind in ('news', 'weekly_update')),
  attachment_path  text,
  attachment_name  text,
  created_by       uuid references public.profiles (id),
  created_at       timestamptz not null default now(),
  reminded_at      timestamptz,
  check (length(btrim(coalesce(title_en, ''))) > 0 or length(btrim(coalesce(title_ar, ''))) > 0),
  check (length(btrim(coalesce(body_en, ''))) > 0 or length(btrim(coalesce(body_ar, ''))) > 0),
  check ((audience = 'class') = (class_id is not null))
);
create table public.announcement_targets (
  announcement_id  uuid not null references public.announcements (id) on delete cascade,
  child_id         uuid not null references public.children (id),
  primary key (announcement_id, child_id)
);
create table public.announcement_reads (
  announcement_id  uuid not null references public.announcements (id) on delete cascade,
  user_id          uuid not null references public.profiles (id),
  read_at          timestamptz not null default now(),
  primary key (announcement_id, user_id)
);

-- Who may see an announcement: management all; a teacher what is for everyone or their class; a parent what is for
-- everyone, their child's class, or their own family.
create function public.cka_announcement_visible(p_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.announcements a where a.id = p_id and (
    public.is_management()
    or (public.auth_role() = 'teacher' and (a.audience = 'all' or (a.audience = 'class' and public.teaches_class(a.class_id))))
    or (public.auth_role() = 'parent' and (a.audience = 'all'
        or (a.audience = 'class' and exists (select 1 from public.parent_children pc join public.children c on c.id = pc.child_id
                                              where pc.parent_id = auth.uid() and c.class_id = a.class_id and c.active))
        or (a.audience = 'families' and exists (select 1 from public.announcement_targets t join public.parent_children pc on pc.child_id = t.child_id
                                                 where t.announcement_id = a.id and pc.parent_id = auth.uid()))))))
$$;

-- The active parents an announcement is meant for.
create function public.cka_announcement_parents(p_id uuid) returns setof uuid
language sql stable security definer set search_path = public as $$
  select distinct pc.parent_id
    from public.announcements a
    join public.parent_children pc on true
    join public.children c on c.id = pc.child_id and c.active
    join public.profiles p on p.id = pc.parent_id and p.active
   where a.id = p_id and (a.audience = 'all'
      or (a.audience = 'class' and c.class_id = a.class_id)
      or (a.audience = 'families' and exists (select 1 from public.announcement_targets t where t.announcement_id = a.id and t.child_id = c.id)))
$$;

alter table public.announcements        enable row level security;
alter table public.announcement_targets enable row level security;
alter table public.announcement_reads   enable row level security;
revoke all on public.announcements, public.announcement_targets, public.announcement_reads from anon, authenticated;
grant select on public.announcements, public.announcement_targets, public.announcement_reads to authenticated;
create policy ann_select    on public.announcements        for select using (public.cka_announcement_visible(id));
create policy ann_tg_select on public.announcement_targets for select using (public.is_management());
create policy ann_rd_select on public.announcement_reads   for select using (public.is_management() or user_id = auth.uid());

-- Private storage for attachments (an image or a PDF); readable by whoever may see the announcement.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values
  ('announcements', 'announcements', false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
on conflict (id) do update set public = false, file_size_limit = 10485760, allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'];

create function public.cka_announcement_file(p_path text) returns boolean
language sql stable security definer set search_path = public as $$
  select case when (storage.foldername(p_path))[1] ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              then public.cka_announcement_visible(((storage.foldername(p_path))[1])::uuid) else false end
$$;
create policy announcements_read on storage.objects for select to authenticated
  using (bucket_id = 'announcements' and public.cka_announcement_file(name));
create policy announcements_upload on storage.objects for insert to authenticated
  with check (bucket_id = 'announcements' and public.is_management());

-- Post an announcement. The page makes the id first (so the attachment can be uploaded into its own folder).
create function public.announcement_post(p_id uuid, p_title_en text, p_title_ar text, p_body_en text, p_body_ar text, p_audience text, p_class uuid,
                                         p_children uuid[], p_important boolean, p_kind text, p_attachment_path text, p_attachment_name text) returns uuid
language plpgsql security definer set search_path = public as $$
declare s uuid;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  if p_id is null then raise exception 'Invalid request'; end if;
  if p_audience not in ('all', 'class', 'families') then raise exception 'Choose who it is for'; end if;
  if p_audience = 'class' and not exists (select 1 from public.classes where id = p_class) then raise exception 'Choose a class'; end if;
  if p_audience = 'families' and (p_children is null or cardinality(p_children) = 0) then raise exception 'Choose at least one family'; end if;
  if p_attachment_path is not null and (p_attachment_path not like p_id::text || '/%' or p_attachment_path like '%..%') then raise exception 'Invalid attachment'; end if;
  insert into public.announcements (id, title_en, title_ar, body_en, body_ar, audience, class_id, important, kind, attachment_path, attachment_name, created_by)
  values (p_id, nullif(btrim(coalesce(p_title_en, '')), ''), nullif(btrim(coalesce(p_title_ar, '')), ''), nullif(btrim(coalesce(p_body_en, '')), ''), nullif(btrim(coalesce(p_body_ar, '')), ''),
          p_audience, case when p_audience = 'class' then p_class end, coalesce(p_important, false), case when p_kind = 'weekly_update' then 'weekly_update' else 'news' end,
          nullif(p_attachment_path, ''), nullif(left(p_attachment_name, 200), ''), auth.uid());
  if p_audience = 'families' then
    insert into public.announcement_targets (announcement_id, child_id) select p_id, c from unnest(p_children) c where exists (select 1 from public.children where id = c);
  end if;
  for s in select * from public.cka_announcement_parents(p_id) loop
    perform public.cka_enqueue_email(s, 'announcement_new', jsonb_build_object('important', coalesce(p_important, false)), 'ann:' || p_id || ':' || s);
  end loop;
  return p_id;
end $$;

create function public.announcement_mark_read(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.auth_role() <> 'parent' or not public.cka_announcement_visible(p_id) then return; end if;
  insert into public.announcement_reads (announcement_id, user_id) values (p_id, auth.uid()) on conflict do nothing;
end $$;

-- Admin: who has opened it, and who has not.
create function public.announcement_stats(p_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare out jsonb;
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  select jsonb_build_object(
    'total', (select count(*) from public.cka_announcement_parents(p_id)),
    'read', (select count(*) from public.announcement_reads r where r.announcement_id = p_id and r.user_id in (select * from public.cka_announcement_parents(p_id))),
    'readers', coalesce((select jsonb_agg(jsonb_build_object('name', p.full_name, 'read_at', r.read_at) order by r.read_at)
                from public.announcement_reads r join public.profiles p on p.id = r.user_id where r.announcement_id = p_id), '[]'),
    'unread', coalesce((select jsonb_agg(jsonb_build_object('name', p.full_name, 'phone', p.phone) order by p.full_name)
                from public.cka_announcement_parents(p_id) u join public.profiles p on p.id = u
               where not exists (select 1 from public.announcement_reads r where r.announcement_id = p_id and r.user_id = u)), '[]')) into out;
  return out;
end $$;

create function public.announcement_remove(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_management() then raise exception 'Not allowed'; end if;
  delete from public.announcements where id = p_id;
end $$;

